import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { validateDataFlowTypes } from "../../composer/validation.js";
import type { ComposeStepInput } from "../../composer/types.js";

/** Field access is only valid on an object, and sampling is plain text unless in JSON mode. */
describe("validateDataFlowTypes", () => {
  it("rejects field access on a plain-text sampling result", () => {
    const steps: ComposeStepInput[] = [
      {
        id: "analyze",
        label: "Analyze",
        // No responseFormat and no JSON intent -> plain text string.
        config: { type: "sampling", prompt: "Analyze: {{params.msg}}" },
      },
      {
        id: "route",
        label: "Route",
        config: {
          type: "conditional",
          condition: "steps.analyze.toxicityScore > 0.7",
          thenStep: "act",
        },
        dependsOn: ["analyze"],
      },
    ];
    assert.throws(
      () => validateDataFlowTypes(steps),
      /plain text strings with no properties/,
    );
  });

  it("allows field access when the sampling step declares responseFormat: json", () => {
    const steps: ComposeStepInput[] = [
      {
        id: "analyze",
        label: "Analyze",
        config: {
          type: "sampling",
          prompt: "Analyze {{params.msg}} and return a JSON object",
          responseFormat: "json",
        },
      },
      {
        id: "route",
        label: "Route",
        config: {
          type: "conditional",
          condition: "steps.analyze.toxicityScore > 0.7",
          thenStep: "act",
        },
        dependsOn: ["analyze"],
      },
    ];
    assert.doesNotThrow(() => validateDataFlowTypes(steps));
  });

  it("allows field access when the prompt signals JSON intent (no explicit responseFormat)", () => {
    const steps: ComposeStepInput[] = [
      {
        id: "analyze",
        label: "Analyze",
        config: {
          type: "sampling",
          prompt: "Analyze {{params.msg}} and respond with a JSON object",
        },
      },
      {
        id: "route",
        label: "Route",
        config: {
          type: "conditional",
          condition: "steps.analyze.toxicityScore > 0.7",
          thenStep: "act",
        },
        dependsOn: ["analyze"],
      },
    ];
    assert.doesNotThrow(() => validateDataFlowTypes(steps));
  });

  it("allows string method calls on a plain-text sampling result", () => {
    const steps: ComposeStepInput[] = [
      {
        id: "analyze",
        label: "Analyze",
        config: { type: "sampling", prompt: "Check: {{params.msg}}" },
      },
      {
        id: "route",
        label: "Route",
        config: {
          type: "conditional",
          condition: 'steps.analyze.includes("toxic")',
          thenStep: "act",
        },
        dependsOn: ["analyze"],
      },
    ];
    assert.doesNotThrow(() => validateDataFlowTypes(steps));
  });

  it("rejects field access on a conditional (boolean) result", () => {
    const steps: ComposeStepInput[] = [
      {
        id: "check",
        label: "Check",
        config: { type: "conditional", condition: "true", thenStep: "next" },
      },
      {
        id: "next",
        label: "Next",
        config: { type: "transform", expression: "steps.check.someField" },
        dependsOn: ["check"],
      },
    ];
    assert.throws(
      () => validateDataFlowTypes(steps),
      /booleans with no properties/,
    );
  });

  it("allows field access on api_call results", () => {
    const steps: ComposeStepInput[] = [
      {
        id: "fetch",
        label: "Fetch",
        config: {
          type: "api_call",
          operationId: "get-api-v1-channels-list",
          inputMapping: {},
        },
      },
      {
        id: "extract",
        label: "Extract",
        config: { type: "transform", expression: "steps.fetch.channels" },
        dependsOn: ["fetch"],
      },
    ];
    assert.doesNotThrow(() => validateDataFlowTypes(steps));
  });

  it("allows field access on elicitation results", () => {
    const steps: ComposeStepInput[] = [
      {
        id: "ask",
        label: "Ask",
        config: {
          type: "elicitation",
          message: "Confirm?",
          requestedSchema: {
            type: "object",
            properties: { confirm: { type: "boolean" } },
          },
        },
      },
      {
        id: "check",
        label: "Check",
        config: {
          type: "conditional",
          condition: "steps.ask.confirm === true",
          thenStep: "done",
        },
        dependsOn: ["ask"],
      },
    ];
    assert.doesNotThrow(() => validateDataFlowTypes(steps));
  });
});

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import type { JSONSchema7 } from "json-schema";
import {
  normalizeEventParamShorthand,
  normalizeTemplateFields,
} from "../../composer/normalization.js";
import { ComposerError, type ComposeStepInput } from "../../composer/types.js";
import type { ApiCallStep } from "../../workflow/types.js";

function apiStep(
  id: string,
  config: Partial<ApiCallStep> & { inputMapping: Record<string, unknown> },
): ComposeStepInput {
  return {
    id,
    label: id,
    config: {
      type: "api_call",
      operationId: `op_${id}`,
      ...config,
    } as ApiCallStep,
  };
}

describe("normalizeTemplateFields - forEach alias scoping", () => {
  it("rewrites an alias reference inside the owning step's inputMapping", () => {
    const steps: ComposeStepInput[] = [
      apiStep("send", {
        forEach: "{{steps.list.channels}}",
        as: "ch",
        inputMapping: { roomId: "{{ch.name}}" },
      }),
    ];

    const warnings = normalizeTemplateFields(steps);

    const cfg = steps[0].config as ApiCallStep;
    assert.equal(cfg.inputMapping.roomId, "{{steps.ch.name}}");
    assert.ok(
      warnings.some((w) => w.code === "AS_VAR_REWRITTEN"),
      "expected an AS_VAR_REWRITTEN warning for the in-scope rewrite",
    );
  });

  it("throws when a non-owning step references the alias", () => {
    const steps: ComposeStepInput[] = [
      apiStep("send", {
        forEach: "{{steps.list.channels}}",
        as: "ch",
        inputMapping: { roomId: "{{ch.name}}" },
      }),
      apiStep("notify", {
        // "ch" is out of scope here — it belongs to the "send" loop.
        inputMapping: { text: "posted to {{ch.name}}" },
      }),
    ];

    assert.throws(
      () => normalizeTemplateFields(steps),
      (err: unknown) => {
        assert.ok(err instanceof ComposerError);
        assert.match(err.message, /forEach alias "ch"/);
        assert.match(err.message, /notify/);
        return true;
      },
    );
  });

  it("throws when the owning step uses its alias in the forEach collection expression", () => {
    const steps: ComposeStepInput[] = [
      apiStep("send", {
        // The alias does not exist yet while the collection is being resolved.
        forEach: "{{ch.items}}",
        as: "ch",
        inputMapping: { roomId: "static" },
      }),
    ];

    assert.throws(
      () => normalizeTemplateFields(steps),
      (err: unknown) =>
        err instanceof ComposerError && /forEach alias "ch"/.test(err.message),
    );
  });

  it("throws when a step references another loop's alias inside its own inputMapping", () => {
    const steps: ComposeStepInput[] = [
      apiStep("outer", {
        forEach: "{{steps.a.list}}",
        as: "outerItem",
        inputMapping: { id: "{{outerItem.id}}" },
      }),
      apiStep("inner", {
        forEach: "{{steps.b.list}}",
        as: "innerItem",
        // References "outerItem" which belongs to the "outer" step.
        inputMapping: { id: "{{innerItem.id}}", parent: "{{outerItem.id}}" },
      }),
    ];

    assert.throws(
      () => normalizeTemplateFields(steps),
      (err: unknown) =>
        err instanceof ComposerError &&
        /forEach alias "outerItem"/.test(err.message),
    );
  });

  it("leaves canonical steps.<alias> references untouched and does not throw", () => {
    const steps: ComposeStepInput[] = [
      apiStep("send", {
        forEach: "{{steps.list.channels}}",
        as: "ch",
        inputMapping: { roomId: "{{steps.ch.name}}" },
      }),
    ];

    const warnings = normalizeTemplateFields(steps);

    const cfg = steps[0].config as ApiCallStep;
    assert.equal(cfg.inputMapping.roomId, "{{steps.ch.name}}");
    assert.ok(!warnings.some((w) => w.code === "AS_VAR_REWRITTEN"));
  });

  it("scopes each alias independently so identical rewrites happen only in their own step", () => {
    const steps: ComposeStepInput[] = [
      apiStep("first", {
        forEach: "{{steps.a.rows}}",
        as: "row",
        inputMapping: { v: "{{row.value}}" },
      }),
      apiStep("second", {
        forEach: "{{steps.b.rows}}",
        as: "row",
        inputMapping: { v: "{{row.value}}" },
      }),
    ];

    const warnings = normalizeTemplateFields(steps);

    assert.equal(
      (steps[0].config as ApiCallStep).inputMapping.v,
      "{{steps.row.value}}",
    );
    assert.equal(
      (steps[1].config as ApiCallStep).inputMapping.v,
      "{{steps.row.value}}",
    );
    assert.equal(
      warnings.filter((w) => w.code === "AS_VAR_REWRITTEN").length,
      2,
    );
  });

  it("keeps alias precedence: an out-of-scope ref is never rescued into a param", () => {
    // The alias shares a param's name on purpose: it must stay an alias for the scope check.
    const params: JSONSchema7 = {
      type: "object",
      properties: { channel: { type: "object" } },
    };
    const steps: ComposeStepInput[] = [
      apiStep("loop", {
        forEach: "{{steps.list.channels}}",
        as: "channel",
        inputMapping: { roomId: "{{channel.id}}" },
      }),
      apiStep("after", {
        inputMapping: { roomId: "{{channel.id}}" },
      }),
    ];

    // Runs first in the pipeline; must leave the alias references untouched.
    normalizeEventParamShorthand(steps, params);
    assert.equal(
      (steps[1].config as ApiCallStep).inputMapping.roomId,
      "{{channel.id}}",
      "event-param normalizer must not rewrite an alias-named reference to params.*",
    );

    assert.throws(
      () => normalizeTemplateFields(steps),
      (err: unknown) =>
        err instanceof ComposerError &&
        /forEach alias "channel"/.test(err.message),
    );
  });
});

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { inferSamplingResponseSchemas } from "../../composer/validation.js";
import type { ComposeStepInput } from "../../composer/types.js";
import type { SamplingStep } from "../../workflow/types.js";

describe("inferSamplingResponseSchemas", () => {
  it("infers a responseSchema from downstream dot access, guessing types from usage", () => {
    const steps: ComposeStepInput[] = [
      {
        id: "rank",
        label: "Rank",
        config: {
          type: "sampling",
          prompt:
            "Return a JSON object with fields: safe, score and items. {{params.msg}}",
          responseFormat: "json",
        },
      },
      {
        id: "gate",
        label: "Gate",
        config: {
          type: "conditional",
          condition: "steps.rank.safe === true",
          thenStep: "join",
        },
        dependsOn: ["rank"],
      },
      {
        id: "join",
        label: "Join",
        config: {
          type: "transform",
          expression: "steps.rank.items.join(', ') + steps.rank.score",
        },
        dependsOn: ["gate"],
      },
    ];

    const warnings = inferSamplingResponseSchemas(steps);
    const cfg = steps[0].config as SamplingStep;

    assert.deepEqual(cfg.responseSchema, {
      safe: "boolean",
      items: "array",
      score: "string",
    });
    assert.equal(warnings.length, 0);
  });

  it("infers JSON mode from prompt intent even without responseFormat", () => {
    const steps: ComposeStepInput[] = [
      {
        id: "rank",
        label: "Rank",
        config: {
          type: "sampling",
          prompt: "Respond with a JSON object containing a score field.",
        },
      },
      {
        id: "use",
        label: "Use",
        config: { type: "transform", expression: "steps.rank.score" },
        dependsOn: ["rank"],
      },
    ];

    inferSamplingResponseSchemas(steps);
    const cfg = steps[0].config as SamplingStep;
    assert.deepEqual(cfg.responseSchema, { score: "string" });
  });

  it("recognizes bracket-notation field access", () => {
    const steps: ComposeStepInput[] = [
      {
        id: "rank",
        label: "Rank",
        config: {
          type: "sampling",
          prompt: "Return JSON with a safe field.",
          responseFormat: "json",
        },
      },
      {
        id: "use",
        label: "Use",
        config: { type: "transform", expression: 'steps.rank["safe"]' },
        dependsOn: ["rank"],
      },
    ];

    inferSamplingResponseSchemas(steps);
    const cfg = steps[0].config as SamplingStep;
    assert.deepEqual(cfg.responseSchema, { safe: "string" });
  });

  it("warns when a consumed field is not mentioned in the prompt", () => {
    const steps: ComposeStepInput[] = [
      {
        id: "rank",
        label: "Rank",
        config: {
          type: "sampling",
          prompt: "Return a JSON object.",
          responseFormat: "json",
        },
      },
      {
        id: "use",
        label: "Use",
        config: { type: "transform", expression: "steps.rank.score" },
        dependsOn: ["rank"],
      },
    ];

    const warnings = inferSamplingResponseSchemas(steps);
    assert.equal(warnings.length, 1);
    assert.equal(warnings[0].code, "SAMPLING_SCHEMA_MISMATCH");
    assert.equal(warnings[0].stepId, "rank");
  });

  it("leaves plain-text sampling steps untouched", () => {
    const steps: ComposeStepInput[] = [
      {
        id: "rank",
        label: "Rank",
        config: { type: "sampling", prompt: "Summarize: {{params.msg}}" },
      },
    ];

    const warnings = inferSamplingResponseSchemas(steps);
    const cfg = steps[0].config as SamplingStep;
    assert.equal(cfg.responseSchema, undefined);
    assert.equal(warnings.length, 0);
  });

  it("ignores JS builtin methods when inferring fields", () => {
    const steps: ComposeStepInput[] = [
      {
        id: "rank",
        label: "Rank",
        config: {
          type: "sampling",
          prompt: "Return JSON.",
          responseFormat: "json",
        },
      },
      {
        id: "use",
        label: "Use",
        config: { type: "transform", expression: "steps.rank.length" },
        dependsOn: ["rank"],
      },
    ];

    inferSamplingResponseSchemas(steps);
    const cfg = steps[0].config as SamplingStep;
    assert.equal(cfg.responseSchema, undefined);
  });
});

import type { JSONSchema7 } from "json-schema";
import type {
  ConditionalStep,
  SamplingStep,
  StepConfig,
  TransformStep,
} from "../workflow/types.js";
import {
  ComposerError,
  type ComposerWarning,
  type ComposeStepInput,
} from "./types.js";
import {
  BARE_PARAM_REF_RE,
  JS_BUILTIN_METHODS,
  PARAM_REF_RE,
  STEP_FIELD_ACCESS_RE,
  STEP_REF_RE,
  extractTemplateStrings,
} from "./utils.js";
import {
  autoReturnExpression,
  validateSafeExpression,
} from "../workflow/expression-security.js";
import { detectJsonIntent } from "../workflow/json-intent.js";

export function validateUniqueIds(steps: ComposeStepInput[]): void {
  const ids = new Set<string>();
  for (const step of steps) {
    if (ids.has(step.id)) {
      throw new ComposerError(`Duplicate step ID: "${step.id}"`);
    }
    ids.add(step.id);
  }
}

export function validateReferences(steps: ComposeStepInput[]): void {
  const ids = new Set(steps.map((s) => s.id));

  for (const step of steps) {
    if (step.dependsOn) {
      for (const dep of step.dependsOn) {
        if (!ids.has(dep)) {
          throw new ComposerError(
            `Step "${step.id}" depends on unknown step "${dep}"`,
          );
        }
        if (dep === step.id) {
          throw new ComposerError(`Step "${step.id}" cannot depend on itself`);
        }
      }
    }

    if (step.config.type === "conditional") {
      const cfg = step.config as ConditionalStep;
      if (!ids.has(cfg.thenStep)) {
        throw new ComposerError(
          `Step "${step.id}" references unknown thenStep "${cfg.thenStep}"`,
        );
      }
      if (cfg.elseStep && !ids.has(cfg.elseStep)) {
        throw new ComposerError(
          `Step "${step.id}" references unknown elseStep "${cfg.elseStep}"`,
        );
      }
    }
  }
}

export function detectCycles(steps: ComposeStepInput[]): void {
  const adj = new Map<string, string[]>();
  for (const step of steps) {
    adj.set(step.id, step.dependsOn ?? []);
  }

  const visited = new Set<string>();
  const inStack = new Set<string>();

  function dfs(node: string, path: string[]): void {
    if (inStack.has(node)) {
      const cycleStart = path.indexOf(node);
      const cycle = path.slice(cycleStart).concat(node);
      throw new ComposerError(
        `Circular dependency detected: ${cycle.join(" → ")}`,
      );
    }
    if (visited.has(node)) return;

    visited.add(node);
    inStack.add(node);

    for (const dep of adj.get(node) ?? []) {
      dfs(dep, [...path, node]);
    }

    inStack.delete(node);
  }

  for (const step of steps) {
    if (!visited.has(step.id)) {
      dfs(step.id, []);
    }
  }
}

export function validateStepConfig(step: ComposeStepInput): void {
  const cfg = step.config;
  switch (cfg.type) {
    case "api_call":
      if (!cfg.operationId) {
        throw new ComposerError(
          `Step "${step.id}" (api_call): operationId is required`,
        );
      }
      break;
    case "sampling":
      if (!cfg.prompt) {
        throw new ComposerError(
          `Step "${step.id}" (sampling): prompt is required`,
        );
      }
      if (cfg.content) {
        for (const item of cfg.content) {
          if (item.type === "text" && !item.text) {
            throw new ComposerError(
              `Step "${step.id}" (sampling): content text item requires a text field`,
            );
          }
          if (item.type === "image" && !item.url) {
            throw new ComposerError(
              `Step "${step.id}" (sampling): content image item requires a url field`,
            );
          }
        }
      }
      break;
    case "elicitation":
      if (!cfg.message) {
        throw new ComposerError(
          `Step "${step.id}" (elicitation): message is required`,
        );
      }
      if (!cfg.requestedSchema) {
        throw new ComposerError(
          `Step "${step.id}" (elicitation): requestedSchema is required`,
        );
      }
      break;
    case "transform":
      if (!cfg.expression) {
        throw new ComposerError(
          `Step "${step.id}" (transform): expression is required`,
        );
      }
      break;
    case "conditional":
      if (!cfg.condition) {
        throw new ComposerError(
          `Step "${step.id}" (conditional): condition is required`,
        );
      }
      if (!cfg.thenStep) {
        throw new ComposerError(
          `Step "${step.id}" (conditional): thenStep is required`,
        );
      }
      break;
    default:
      throw new ComposerError(
        `Step "${step.id}": unknown step type "${(cfg as { type: string }).type}"`,
      );
  }
}

function findDomainKeyHint(field: string, params: JSONSchema7): string | null {
  const props = params.properties as
    | Record<string, JSONSchema7 | boolean>
    | undefined;
  if (!props) return null;
  for (const [key, schema] of Object.entries(props)) {
    if (typeof schema === "boolean") continue;
    const subProps = schema.properties as Record<string, unknown> | undefined;
    if (subProps && (field in subProps || `${field}?` in subProps)) {
      return key;
    }
  }
  return null;
}

export function validateTemplateReferences(
  steps: ComposeStepInput[],
  params: JSONSchema7,
): ComposerWarning[] {
  const warnings: ComposerWarning[] = [];
  const stepIds = new Set(steps.map((s) => s.id));
  for (const step of steps) {
    if (step.config.type === "api_call" && step.config.as) {
      stepIds.add(step.config.as);
    }
  }
  const paramProps = new Set(
    params.properties ? Object.keys(params.properties) : [],
  );

  for (const step of steps) {
    const templates = extractTemplateStrings(step.config);
    for (const tmpl of templates) {
      for (const match of tmpl.matchAll(STEP_REF_RE)) {
        const refId = match[1];
        if (!stepIds.has(refId)) {
          throw new ComposerError(
            `Step "${step.id}" references unknown step "${refId}" in template: "${tmpl.slice(0, 80)}"`,
          );
        }
      }
      if (paramProps.size > 0) {
        for (const match of tmpl.matchAll(PARAM_REF_RE)) {
          const fullPath = match[1];
          const segments = fullPath.split(".");
          const topField = segments[0];
          if (!paramProps.has(topField)) {
            const hint = findDomainKeyHint(topField, params);
            throw new ComposerError(
              `Step "${step.id}" references "params.${topField}" but "${topField}" is not in the workflow params schema. Available: ${[...paramProps].join(", ") || "(none)"}` +
                (hint
                  ? `. Did you mean "params.${hint}.${topField}"? Event params are nested under the domain key.`
                  : ""),
            );
          }
          if (segments.length > 1) {
            const subWarning = validateParamSubField(
              segments,
              params,
              step.id,
              fullPath,
            );
            if (subWarning) warnings.push(subWarning);
          }
        }
        const isJsContext =
          step.config.type === "transform" ||
          step.config.type === "conditional";
        if (isJsContext) {
          for (const match of tmpl.matchAll(BARE_PARAM_REF_RE)) {
            const fullPath = match[1];
            const segments = fullPath.split(".");
            const topField = segments[0];
            if (!paramProps.has(topField)) {
              const hint = findDomainKeyHint(topField, params);
              throw new ComposerError(
                `Step "${step.id}" references "params.${topField}" but "${topField}" is not in the workflow params schema. Available: ${[...paramProps].join(", ") || "(none)"}` +
                  (hint
                    ? `. Did you mean "params.${hint}.${topField}"? Event params are nested under the domain key.`
                    : ""),
              );
            }
            if (segments.length > 1) {
              const subWarning = validateParamSubField(
                segments,
                params,
                step.id,
                fullPath,
              );
              if (subWarning) warnings.push(subWarning);
            }
          }
        }
      }
    }
  }
  return warnings;
}

function validateParamSubField(
  segments: string[],
  schema: JSONSchema7,
  stepId: string,
  fullPath: string,
): ComposerWarning | null {
  let current: JSONSchema7 | boolean | undefined = schema;
  for (let i = 0; i < segments.length; i++) {
    const seg = segments[i];
    if (!current || typeof current === "boolean") return null;
    const props: Record<string, JSONSchema7 | boolean> | undefined = (
      current as JSONSchema7
    ).properties as Record<string, JSONSchema7 | boolean> | undefined;
    if (!props) return null; // No properties defined — can't validate further
    if (!(seg in props)) {
      // Segment not found in this object's properties
      const available = Object.keys(props);
      const parentPath =
        i === 0 ? "params" : `params.${segments.slice(0, i).join(".")}`;
      throw new ComposerError(
        `Step "${stepId}" references "params.${fullPath}" but "${seg}" is not a known property of ${parentPath}. Available: ${available.join(", ")}`,
      );
    }
    const next: JSONSchema7 | boolean = props[seg];
    if (typeof next === "boolean") return null;
    // If this is a leaf type, everything after is JS — allow
    if (i < segments.length - 1 && next.type !== "object" && !next.properties) {
      return null;
    }
    current = next;
  }
  return null;
}

type StepOutputType = "string" | "boolean" | "object" | "unknown";

const STEP_OUTPUT_TYPES: Record<StepConfig["type"], StepOutputType> = {
  sampling: "unknown", // resolved per-step from JSON mode (see resolveStepOutputType)
  conditional: "boolean",
  api_call: "object",
  elicitation: "object",
  transform: "unknown",
};

/** Mirrors the runtime decision, so compose-time validation and execution cannot disagree. */
function isJsonModeSampling(cfg: SamplingStep): boolean {
  return cfg.responseFormat === "json" || detectJsonIntent(cfg);
}

/** Sampling yields a string unless in JSON mode, and field access is only valid on an object. */
function resolveStepOutputType(config: StepConfig): StepOutputType {
  if (config.type === "sampling") {
    return isJsonModeSampling(config) ? "object" : "string";
  }
  return STEP_OUTPUT_TYPES[config.type];
}

export function validateDataFlowTypes(steps: ComposeStepInput[]): void {
  const stepById = new Map(steps.map((s) => [s.id, s]));

  for (const step of steps) {
    const templates = extractTemplateStrings(step.config);
    for (const tmpl of templates) {
      for (const match of tmpl.matchAll(STEP_FIELD_ACCESS_RE)) {
        const refStepId = match[1];
        const field = match[2];
        if (JS_BUILTIN_METHODS.has(field)) continue;
        const refStep = stepById.get(refStepId);
        if (!refStep) continue;

        const outputType = resolveStepOutputType(refStep.config);
        if (outputType === "string") {
          throw new ComposerError(
            `Step "${step.id}" accesses ".${field}" on step "${refStepId}" (${refStep.config.type}), ` +
              `but ${refStep.config.type} results are plain text strings with no properties. ` +
              `Fix: (1) Add a systemPrompt to step "${refStepId}" asking the LLM to respond in JSON only, ` +
              `(2) Add a transform step after "${refStepId}" with expression 'JSON.parse(steps.${refStepId})', ` +
              `then (3) reference 'steps.<transform_step>.${field}' instead. ` +
              `Alternatively, evaluate the raw string directly (e.g. 'steps.${refStepId}.includes("...")').`,
          );
        }
        if (outputType === "boolean") {
          throw new ComposerError(
            `Step "${step.id}" accesses ".${field}" on step "${refStepId}" (conditional), ` +
              `but conditional results are booleans with no properties. ` +
              `Use the boolean value directly: 'steps.${refStepId} === true'.`,
          );
        }
      }
    }
  }
}

export function validateSafeWorkflowExpressions(
  steps: ComposeStepInput[],
): void {
  for (const step of steps) {
    if (step.config.type === "transform") {
      validateSafeExpression(
        autoReturnExpression((step.config as TransformStep).expression),
        `transform step "${step.id}"`,
      );
    } else if (step.config.type === "conditional") {
      validateSafeExpression(
        (step.config as ConditionalStep).condition,
        `conditional step "${step.id}"`,
      );
    }
  }
}

/**
 * Record the fields downstream steps read off a JSON-mode sampling result, so the shape is
 * explicit and the provider can be steered toward it. Warns when one is never prompted for.
 */
export function inferSamplingResponseSchemas(
  steps: ComposeStepInput[],
): ComposerWarning[] {
  const warnings: ComposerWarning[] = [];

  const jsonSamplingIds = new Set<string>();
  for (const step of steps) {
    if (step.config.type === "sampling" && isJsonModeSampling(step.config)) {
      jsonSamplingIds.add(step.id);
    }
  }
  if (jsonSamplingIds.size === 0) return warnings;

  // For each JSON sampling step: field name -> inferred JSON type.
  const fieldAccesses = new Map<string, Map<string, string>>();
  for (const id of jsonSamplingIds) fieldAccesses.set(id, new Map());

  // steps.X.field, plus a usage hint (=== bool, .join/.map/.length) used to guess the type.
  const FIELD_CONTEXT_RE =
    /steps\.(\w+)\??\.(\w+)\s*(?:===\s*(true|false)|\.join\b|\.map\b|\.filter\b|\.length\b|\.includes\b)?/g;
  // Bracket access: steps.X["field"] or steps.X?.["field"]
  const BRACKET_ACCESS_RE = /steps\.(\w+)\??\[\s*(['"])(\w+)\2\s*\]/g;

  function classifyField(
    refId: string,
    field: string,
    boolLiteral: string | undefined,
    tmpl: string,
    matchStart: number,
    matchEnd: number,
  ): void {
    if (!fieldAccesses.has(refId)) return;
    if (JS_BUILTIN_METHODS.has(field)) return;
    const fields = fieldAccesses.get(refId)!;
    if (fields.has(field)) return;

    let inferredType = "string";
    if (boolLiteral === "true" || boolLiteral === "false") {
      inferredType = "boolean";
    } else if (
      /\.join\b|\.map\b|\.filter\b|\.length\b/.test(
        tmpl.slice(matchStart, matchEnd + 10),
      )
    ) {
      inferredType = "array";
    }
    fields.set(field, inferredType);
  }

  for (const step of steps) {
    const templates = extractTemplateStrings(step.config);
    for (const tmpl of templates) {
      for (const match of tmpl.matchAll(FIELD_CONTEXT_RE)) {
        classifyField(
          match[1],
          match[2],
          match[3],
          tmpl,
          match.index!,
          match.index! + match[0].length,
        );
      }
      for (const match of tmpl.matchAll(BRACKET_ACCESS_RE)) {
        classifyField(
          match[1],
          match[3],
          undefined,
          tmpl,
          match.index!,
          match.index! + match[0].length,
        );
      }
    }
  }

  for (const [stepId, fields] of fieldAccesses) {
    if (fields.size === 0) continue;
    const step = steps.find((s) => s.id === stepId)!;
    if (step.config.type !== "sampling") continue;
    const cfg = step.config;

    const schema: Record<string, string> = {};
    for (const [name, type] of fields) schema[name] = type;
    cfg.responseSchema = schema;

    const promptText =
      `${cfg.prompt || ""} ${cfg.systemPrompt || ""}`.toLowerCase();
    for (const field of fields.keys()) {
      if (!promptText.includes(field.toLowerCase())) {
        warnings.push({
          stepId,
          code: "SAMPLING_SCHEMA_MISMATCH",
          message: `Step "${stepId}" result field "${field}" is used by downstream steps but not mentioned in the sampling prompt — the AI may not include it.`,
        });
      }
    }
  }

  return warnings;
}

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import {
  extractCompactEndpoints,
  extractEndpointByLocation,
  extractFullEndpoints,
} from "../../parser/endpoint-extraction.js";
import type { OpenAPIV3 } from "openapi-types";

function makeSpec(paths: OpenAPIV3.PathsObject): OpenAPIV3.Document {
  return {
    openapi: "3.0.0",
    info: { title: "Test", version: "1.0.0" },
    paths,
  };
}

describe("extractCompactEndpoints", () => {
  it("generates sanitized fallback operationIds", () => {
    const spec = makeSpec({
      "/api/v1/users.info": {
        get: {
          responses: {},
        },
      },
    });

    const endpoints = extractCompactEndpoints(spec, "user-management");

    assert.deepStrictEqual(endpoints, [
      {
        operationId: "get__api_v1_users_info",
        summary: "GET /api/v1/users.info",
        domain: "user-management",
        path: "/api/v1/users.info",
        method: "get",
      },
    ]);
  });

  it("deduplicates repeated operationIds within a domain", () => {
    const spec = makeSpec({
      "/first": {
        get: {
          operationId: "duplicate",
          responses: {},
        },
      },
      "/second": {
        get: {
          operationId: "duplicate",
          responses: {},
        },
      },
    });

    const endpoints = extractCompactEndpoints(spec, "miscellaneous");

    assert.deepStrictEqual(
      endpoints.map((endpoint) => endpoint.operationId),
      ["duplicate", "duplicate_1"],
    );
  });

  it("falls back from summary to description to method and path", () => {
    const spec = makeSpec({
      "/described": {
        get: {
          description: "Description-only endpoint",
          responses: {},
        },
      },
      "/plain": {
        post: {
          responses: {},
        },
      },
    });

    const endpoints = extractCompactEndpoints(spec, "miscellaneous");

    assert.deepStrictEqual(
      endpoints.map((endpoint) => endpoint.summary),
      ["Description-only endpoint", "POST /plain"],
    );
  });
});

describe("extractEndpointByLocation", () => {
  it("extracts the same endpoint shape as the full scan path", () => {
    const spec = makeSpec({
      "/rooms/{rid}": {
        parameters: [
          {
            name: "rid",
            in: "path",
            required: true,
            schema: { type: "string" },
          },
        ],
        post: {
          operationId: "update-room",
          summary: "Update room",
          parameters: [
            {
              name: "includeMembers",
              in: "query",
              schema: { type: "boolean" },
            },
          ],
          requestBody: {
            required: true,
            content: {
              "application/json": {
                schema: {
                  type: "object",
                  properties: {
                    name: { type: "string" },
                  },
                },
              },
            },
          },
          responses: {
            "200": {
              description: "OK",
              content: {
                "application/json": {
                  schema: {
                    type: "object",
                    properties: {
                      success: { type: "boolean" },
                    },
                  },
                },
              },
            },
          },
