      extractEndpointByLocation(spec, "rooms", "get-rooms", "/missing", "get"),
      null,
    );
    assert.equal(
      extractEndpointByLocation(spec, "rooms", "get-rooms", "/rooms", "post"),
      null,
    );
  });
});

