  "toJSON",
  "hasOwnProperty",
  "length",
]);

export function findLiteralRid(
  mapping: Record<string, unknown>,
): string | null {
  function check(val: unknown): string | null {
    if (typeof val === "string" && !val.includes("{{")) return val;
    return null;
  }
  if ("rid" in mapping) {
    const lit = check(mapping.rid);
    if (lit) return lit;
  }
  for (const v of Object.values(mapping)) {
    if (typeof v === "object" && v !== null && !Array.isArray(v)) {
      const nested = v as Record<string, unknown>;
      if ("rid" in nested) {
        const lit = check(nested.rid);
        if (lit) return lit;
      }
    }
  }
  return null;
}

export function collectStringsDeep(obj: unknown, out: string[]): void {
  if (typeof obj === "string") {
    out.push(obj);
  } else if (Array.isArray(obj)) {
    for (const item of obj) collectStringsDeep(item, out);
  } else if (typeof obj === "object" && obj !== null) {
    for (const val of Object.values(obj)) collectStringsDeep(val, out);
  }
}

export function extractTemplateStrings(config: StepConfig): string[] {
  const strings: string[] = [];
  switch (config.type) {
    case "api_call": {
      if (config.inputMapping) {
        collectStringsDeep(
          config.inputMapping as Record<string, unknown>,
          strings,
        );
      }
      if (config.forEach) strings.push(config.forEach);
      break;
    }
    case "sampling": {
      strings.push(config.prompt);
      if (config.systemPrompt) strings.push(config.systemPrompt);
      if (config.content) {
        for (const item of config.content) {
          if (item.type === "text") strings.push(item.text);
          else if (item.type === "image") strings.push(item.url);
        }
      }
      break;
    }
    case "elicitation": {
      strings.push(config.message);
      break;
    }
    case "transform": {
      strings.push(config.expression);
      break;
    }
    case "conditional": {
      strings.push(config.condition);
      break;
    }
  }
  return strings;
}

export function extractStepRefs(config: StepConfig): Set<string> {
  const refs = new Set<string>();
  const isJsContext =
    config.type === "transform" || config.type === "conditional";
  for (const str of extractTemplateStrings(config)) {
    for (const match of str.matchAll(STEP_REF_RE)) {
      refs.add(match[1]);
    }
    if (isJsContext) {
      for (const match of str.matchAll(BARE_STEP_REF_RE)) {
        refs.add(match[1]);
      }
    }
  }
  return refs;
}

export function topologicalSort(steps: ComposeStepInput[]): string[] {
  const inDegree = new Map<string, number>();
  const adj = new Map<string, string[]>();

  for (const step of steps) {
    inDegree.set(step.id, 0);
    adj.set(step.id, []);
  }

  for (const step of steps) {
    for (const dep of step.dependsOn ?? []) {
      adj.get(dep)!.push(step.id);
      inDegree.set(step.id, (inDegree.get(step.id) ?? 0) + 1);
    }
  }

  const queue: string[] = [];
  for (const [id, degree] of inDegree) {
    if (degree === 0) queue.push(id);
  }

  const order: string[] = [];
  while (queue.length > 0) {
    const node = queue.shift()!;
    order.push(node);
    for (const neighbor of adj.get(node) ?? []) {
      const newDegree = (inDegree.get(neighbor) ?? 1) - 1;
      inDegree.set(neighbor, newDegree);
      if (newDegree === 0) queue.push(neighbor);
    }
  }

  return order;
}

import type {
  ApiCallStep,
  ConditionalStep,
  ElicitationStep,
  SamplingStep,
  TransformStep,
} from "../workflow/types.js";
import {
  ComposerError,
  type ComposerWarning,
  type ComposeStepInput,
} from "./types.js";
import {
  JS_BUILTIN_METHODS,
  extractStepRefs,
  extractTemplateStrings,
} from "./utils.js";

export function inferMissingConditionalTargets(
  steps: ComposeStepInput[],
): ComposerWarning[] {
  const warnings: ComposerWarning[] = [];

  for (const step of steps) {
    if (step.config.type !== "conditional") continue;
    const cfg = step.config as ConditionalStep;
    if (cfg.thenStep) continue;

    const dependents = steps.filter(
      (s) => s.id !== step.id && s.dependsOn?.includes(step.id),
    );

    if (cfg.elseStep) {
      const candidates = dependents.filter((s) => s.id !== cfg.elseStep);
      if (candidates.length === 1) {
        cfg.thenStep = candidates[0].id;
        warnings.push({
          stepId: step.id,
          code: "FIELD_AUTO_SET",
          message: `Auto-inferred thenStep="${cfg.thenStep}" for conditional "${step.id}" from its dependents.`,
        });
      } else if (candidates.length === 0) {
        throw new ComposerError(
          `Step "${step.id}" (conditional): thenStep is required. ` +
            `Has elseStep="${cfg.elseStep}" but no other step depends on this conditional to infer thenStep from.`,
        );
      } else {
        throw new ComposerError(
          `Step "${step.id}" (conditional): thenStep is required. ` +
            `Multiple steps depend on it [${candidates.map((s) => s.id).join(", ")}] — specify thenStep explicitly.`,
        );
      }
    } else {
      if (dependents.length === 1) {
        cfg.thenStep = dependents[0].id;
        warnings.push({
          stepId: step.id,
          code: "FIELD_AUTO_SET",
          message: `Auto-inferred thenStep="${cfg.thenStep}" for conditional "${step.id}" from its dependents.`,
        });
      } else if (dependents.length === 0) {
        throw new ComposerError(
          `Step "${step.id}" (conditional): thenStep is required. ` +
            `No steps depend on this conditional — cannot infer thenStep.`,
        );
      } else {
        throw new ComposerError(
          `Step "${step.id}" (conditional): thenStep is required. ` +
            `Multiple steps depend on it [${dependents.map((s) => s.id).join(", ")}] — specify thenStep explicitly.`,
        );
      }
    }
  }

  return warnings;
}

export function injectImplicitDependencies(
  steps: ComposeStepInput[],
): ComposerWarning[] {
  const warnings: ComposerWarning[] = [];
  const ids = new Set(steps.map((s) => s.id));

  for (const step of steps) {
    const deps = new Set(step.dependsOn ?? []);

    const refs = extractStepRefs(step.config);
    for (const refId of refs) {
      if (ids.has(refId) && refId !== step.id && !deps.has(refId)) {
        deps.add(refId);
        warnings.push({
          stepId: step.id,
          code: "IMPLICIT_DEP_ADDED",
          message: `Auto-fixed: "${step.id}" references "${refId}" in templates — dependsOn updated automatically (no action needed).`,
        });
      }
    }

    step.dependsOn = deps.size > 0 ? [...deps] : undefined;
  }

  for (const step of steps) {
    if (step.config.type !== "conditional") continue;
    const cfg = step.config as ConditionalStep;
    for (const targetId of [cfg.thenStep, cfg.elseStep]) {
      if (!targetId) continue;
      const target = steps.find((s) => s.id === targetId);
      if (!target) continue;
      const targetDeps = new Set(target.dependsOn ?? []);
      if (!targetDeps.has(step.id)) {
        targetDeps.add(step.id);
        target.dependsOn = [...targetDeps];
        warnings.push({
          stepId: target.id,
          code: "IMPLICIT_DEP_ADDED",
          message: `Auto-fixed: "${target.id}" is a branch target of conditional "${step.id}" — dependsOn updated automatically (no action needed).`,
        });
      }
    }
  }

  return warnings;
}

export function inferSamplingResponseSchemas(
  steps: ComposeStepInput[],
): ComposerWarning[] {
  const warnings: ComposerWarning[] = [];
  const jsonSamplingIds = new Set<string>();
  for (const step of steps) {
    if (step.config.type === "sampling") {
      const cfg = step.config as SamplingStep;
      if (cfg.responseFormat === "json") {
        jsonSamplingIds.add(step.id);
      }
    }
  }
  if (jsonSamplingIds.size === 0) return warnings;

  const fieldAccesses = new Map<string, Map<string, string>>();
  for (const id of jsonSamplingIds) fieldAccesses.set(id, new Map());

  // Regex that captures: steps.<id>.<field> and optionally a trailing method/operator
  const FIELD_CONTEXT_RE =
    /steps\.(\w+)\.(\w+)\s*(?:===\s*(true|false)|\.join\b|\.map\b|\.filter\b|\.length\b|\.includes\b)?/g;

  for (const step of steps) {
    const templates = extractTemplateStrings(step.config);
    for (const tmpl of templates) {
      for (const match of tmpl.matchAll(FIELD_CONTEXT_RE)) {
        const refId = match[1];
        const field = match[2];
        const boolLiteral = match[3];
        if (!fieldAccesses.has(refId)) continue;
        if (JS_BUILTIN_METHODS.has(field)) continue;
        const fields = fieldAccesses.get(refId)!;
        if (fields.has(field)) continue; // first wins

        let inferredType = "string";
        if (boolLiteral === "true" || boolLiteral === "false") {
          inferredType = "boolean";
        } else if (
          /\.join\b|\.map\b|\.filter\b|\.length\b/.test(
            tmpl.slice(match.index!, match.index! + match[0].length + 10),
          )
        ) {
          inferredType = "array";
        }
        fields.set(field, inferredType);
      }
    }
  }

  for (const [stepId, fields] of fieldAccesses) {
    if (fields.size === 0) continue;
    const step = steps.find((s) => s.id === stepId)!;
    const cfg = step.config as SamplingStep;
    const schema: Record<string, string> = {};
    for (const [name, type] of fields) schema[name] = type;
    cfg.responseSchema = schema;

    const promptText =
      `${cfg.prompt || ""} ${cfg.systemPrompt || ""}`.toLowerCase();
    for (const field of fields.keys()) {
      if (!promptText.includes(field.toLowerCase())) {
        warnings.push({
          stepId,
          code: "SAMPLING_SCHEMA_MISMATCH",
          message: `Step "${stepId}" result field "${field}" is used by downstream steps but not mentioned in the sampling prompt — the AI may not include it.`,
        });
      }
    }
  }

  return warnings;
}

export function inferOutputPath(steps: ComposeStepInput[]): ComposerWarning[] {
  const warnings: ComposerWarning[] = [];
  const apiCallSteps = new Map<string, ApiCallStep>();
  for (const step of steps) {
    if (step.config.type === "api_call") {
      apiCallSteps.set(step.id, step.config as ApiCallStep);
    }
  }
  if (apiCallSteps.size === 0) return warnings;

  const fieldAccesses = new Map<string, Set<string>>();
  for (const [id] of apiCallSteps) fieldAccesses.set(id, new Set());

  for (const step of steps) {
    const strings = extractTemplateStrings(step.config);
    const isJs =
      step.config.type === "transform" || step.config.type === "conditional";
    for (const str of strings) {
      for (const m of str.matchAll(/\{\{steps\.(\w+)\.(\w+)/g)) {
        const [, stepId, field] = m;
        if (fieldAccesses.has(stepId) && !JS_BUILTIN_METHODS.has(field)) {
          fieldAccesses.get(stepId)!.add(field);
        }
      }
      if (isJs) {
        for (const m of str.matchAll(/\bsteps\.(\w+)\??\.(\w+)/g)) {
          const [, stepId, field] = m;
          if (fieldAccesses.has(stepId) && !JS_BUILTIN_METHODS.has(field)) {
            fieldAccesses.get(stepId)!.add(field);
          }
        }
      }
    }
  }

  for (const [stepId, apiCfg] of apiCallSteps) {
    const accessed = fieldAccesses.get(stepId)!;
    if (accessed.size === 0) continue;

    if (apiCfg.outputPath) {
      if (accessed.has(apiCfg.outputPath)) {
        rewriteStepRefs(steps, stepId, apiCfg.outputPath);
        warnings.push({
          stepId,
          code: "OUTPUT_PATH_REF_FIXED",
          message:
            `Redundant extraction fixed: downstream refs used "steps.${stepId}.${apiCfg.outputPath}" ` +
            `but outputPath already extracts "${apiCfg.outputPath}". Refs rewritten to "steps.${stepId}".`,
        });
      }
    } else if (accessed.size === 1) {
      const field = [...accessed][0];
      apiCfg.outputPath = field;
      rewriteStepRefs(steps, stepId, field);
      warnings.push({
        stepId,
        code: "OUTPUT_PATH_INFERRED",
        message:
          `Auto-inferred outputPath "${field}": all downstream refs access "steps.${stepId}.${field}". ` +
          `Refs rewritten to "steps.${stepId}".`,
      });
    }
  }

  return warnings;
}

/** Strip extracted outputPath field from downstream step refs (template + JS + optional chaining). */
function rewriteStepRefs(
  steps: ComposeStepInput[],
  stepId: string,
  field: string,
): void {
  const tmplRe = new RegExp(
    `(\\{\\{steps\\.${stepId})\\.${field}(?=\\.|\\}|\\s|\\))`,
    "g",
  );
  const jsRe = new RegExp(
    `(\\bsteps\\.${stepId})\\??\\.${field}(?=\\??\\.|\\b|\\)|\\s|$|,|;|\\])`,
    "g",
  );

  for (const step of steps) {
    const cfg = step.config;

    switch (cfg.type) {
      case "api_call": {
        const apiCfg = cfg as ApiCallStep;
        if (apiCfg.inputMapping) {
          apiCfg.inputMapping = rewriteDeep(
            apiCfg.inputMapping,
            tmplRe,
          ) as Record<string, unknown>;
        }
        if (apiCfg.forEach) {
          apiCfg.forEach = apiCfg.forEach.replace(tmplRe, "$1");
        }
        break;
      }
      case "sampling": {
        const sCfg = cfg as SamplingStep;
        sCfg.prompt = sCfg.prompt.replace(tmplRe, "$1");
        if (sCfg.systemPrompt)
          sCfg.systemPrompt = sCfg.systemPrompt.replace(tmplRe, "$1");
        if (sCfg.content) {
          for (const item of sCfg.content) {
            if (item.type === "text")
              item.text = item.text.replace(tmplRe, "$1");
          }
        }
        break;
      }
      case "elicitation": {
        const eCfg = cfg as ElicitationStep;
        eCfg.message = eCfg.message.replace(tmplRe, "$1");
        break;
      }
      case "transform": {
        const tCfg = cfg as TransformStep;
        tCfg.expression = tCfg.expression.replace(jsRe, "$1");
        tCfg.expression = tCfg.expression.replace(tmplRe, "$1");
        break;
      }
      case "conditional": {
        const cCfg = cfg as ConditionalStep;
        cCfg.condition = cCfg.condition.replace(jsRe, "$1");
        cCfg.condition = cCfg.condition.replace(tmplRe, "$1");
        break;
      }
    }
  }
}

/** Recursively replace in all string values of an object/array. */
function rewriteDeep(value: unknown, re: RegExp): unknown {
  if (typeof value === "string") return value.replace(re, "$1");
  if (Array.isArray(value)) return value.map((item) => rewriteDeep(item, re));
  if (typeof value === "object" && value !== null) {
    const result: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value)) {
      result[k] = rewriteDeep(v, re);
    }
    return result;
  }
  return value;
}

import type { JSONSchema7 } from "json-schema";
import type {
  ApiCallStep,
  ConditionalStep,
  SamplingStep,
} from "../workflow/types.js";
import {
  ComposerError,
  type ComposerWarning,
  type ComposeStepInput,
} from "./types.js";
import { extractStepRefs, findLiteralRid } from "./utils.js";

export function generateSemanticWarnings(
  steps: ComposeStepInput[],
  params?: JSONSchema7,
): ComposerWarning[] {
  const warnings: ComposerWarning[] = [];
  const hasParams =
    params &&
    Object.keys((params.properties as Record<string, unknown>) ?? {}).length >
      0;

  const referencedSteps = new Set<string>();
  for (const step of steps) {
    for (const dep of step.dependsOn ?? []) referencedSteps.add(dep);
    const refs = extractStepRefs(step.config);
    for (const r of refs) referencedSteps.add(r);
    if (step.config.type === "conditional") {
      const cfg = step.config as ConditionalStep;
      referencedSteps.add(cfg.thenStep);
      if (cfg.elseStep) referencedSteps.add(cfg.elseStep);
    }
  }

  for (const step of steps) {
    if (step.config.type === "sampling") {
      let referenced = false;
      for (const other of steps) {
        if (other.id === step.id) continue;
        const refs = extractStepRefs(other.config);
        if (refs.has(step.id)) {
          referenced = true;
          break;
        }
      }
      if (!referenced) {
        warnings.push({
          stepId: step.id,
          code: "UNUSED_SAMPLING",
          message: `Sampling step "${step.id}" result is never referenced by any other step. This wastes an LLM call.`,
        });
      }

      const cfg = step.config as SamplingStep;
      const allText = [
        cfg.prompt ?? "",
        cfg.systemPrompt ?? "",
        ...(cfg.content ?? []).map((c) =>
          c.type === "text" ? (c.text ?? "") : (c.url ?? ""),
        ),
      ].join(" ");
      const hasTemplateRef = /\{\{(params|steps)\./.test(allText);
      if (!hasTemplateRef && hasParams) {
        throw new ComposerError(
          `Sampling step "${step.id}" prompt does not reference any {{params.*}} or {{steps.*}} data. ` +
            `The AI will have no input to analyze. Include the relevant data in the prompt ` +
            `(e.g. {{params.message.text}}).`,
        );
      }
    }
  }

  const forward = new Map<string, Set<string>>();
  for (const step of steps) {
    if (!forward.has(step.id)) forward.set(step.id, new Set());
    for (const dep of step.dependsOn ?? []) {
      if (!forward.has(dep)) forward.set(dep, new Set());
      forward.get(dep)!.add(step.id);
    }
    if (step.config.type === "conditional") {
      const cfg = step.config as ConditionalStep;
      forward.get(step.id)!.add(cfg.thenStep);
      if (cfg.elseStep) forward.get(step.id)!.add(cfg.elseStep);
    }
  }

  const reachable = new Set<string>();
  const queue: string[] = [];
  for (const step of steps) {
    if (!step.dependsOn || step.dependsOn.length === 0) {
      reachable.add(step.id);
      queue.push(step.id);
    }
  }
  while (queue.length > 0) {
    const id = queue.shift()!;
    for (const next of forward.get(id) ?? []) {
      if (!reachable.has(next)) {
        reachable.add(next);
        queue.push(next);
      }
    }
  }

  for (const step of steps) {
    if (!reachable.has(step.id)) {
      warnings.push({
        stepId: step.id,
        code: "ORPHANED_STEP",
        message: `Step "${step.id}" is not reachable from any entry point. It will never execute.`,
      });
    }
  }

  const rootSteps = steps.filter(
    (s) => !s.dependsOn || s.dependsOn.length === 0,
  );
  if (rootSteps.length > 1) {
    const rootIds = rootSteps.map((s) => s.id);
    warnings.push({
      stepId: null,
      code: "MULTIPLE_ROOTS",
      message:
        `Workflow has ${rootSteps.length} root steps (no dependsOn): [${rootIds.join(", ")}]. ` +
        `Most workflows should have exactly 1 entry point. ` +
        `If these steps should run after other steps, add them to dependsOn.`,
    });
  }

  const opCounts = new Map<string, string[]>();
  for (const step of steps) {
    if (step.config.type === "api_call") {
      const opId = (step.config as ApiCallStep).operationId;
      const list = opCounts.get(opId) ?? [];
      list.push(step.id);
      opCounts.set(opId, list);
    }
  }
  for (const [opId, stepIds] of opCounts) {
    if (stepIds.length > 1) {
      warnings.push({
        stepId: null,
        code: "DUPLICATE_API_CALL",
        message: `Multiple steps (${stepIds.join(", ")}) call the same endpoint "${opId}". Is this intentional?`,
      });
    }
  }

  for (const step of steps) {
    if (step.config.type !== "api_call") continue;
    const cfg = step.config as ApiCallStep;
    if (
      !cfg.operationId.includes("chat_sendMessage") &&
      !cfg.operationId.includes("chat.sendMessage")
    )
      continue;
    const rid = findLiteralRid(cfg.inputMapping);
    if (rid) {
      warnings.push({
        stepId: step.id,
        code: "HARDCODED_RID",
        message:
          `Step "${step.id}" uses chat.sendMessage with hardcoded rid "${rid}". ` +
          `The rid field requires a room ID (e.g. "6oaKzj..."), not a channel name. ` +
          `Use "post-api-v1-chat_postMessage" with { channel: "#${rid}", text: "..." } instead, ` +
          `which resolves channel names natively.`,
      });
    }
  }

  const depthCache = new Map<string, number>();
  const stepMap = new Map(steps.map((s) => [s.id, s]));
  function getDepth(id: string): number {
    if (depthCache.has(id)) return depthCache.get(id)!;
    const step = stepMap.get(id);
    if (!step || !step.dependsOn || step.dependsOn.length === 0) {
      depthCache.set(id, 0);
      return 0;
    }
    const maxParent = Math.max(...step.dependsOn.map(getDepth));
    const depth = maxParent + 1;
    depthCache.set(id, depth);
    return depth;
  }
  for (const step of steps) {
    const depth = getDepth(step.id);
    if (depth > 8) {
      warnings.push({
        stepId: step.id,
        code: "DEEP_CHAIN",
        message: `Step "${step.id}" is ${depth} levels deep in the dependency chain. Consider simplifying.`,
      });
      break;
    }
  }

  return warnings;
}

import type { JSONSchema7 } from "json-schema";
import type { StepConfig, WorkflowDefinition } from "../workflow/types.js";

export interface ComposeWorkflowInput {
  name: string;
  description: string;
  params: JSONSchema7;
  steps: ComposeStepInput[];
}

export interface ComposeStepInput {
  id: string;
  label: string;
  config: StepConfig;
  dependsOn?: string[];
}

export interface ComposerWarning {
  stepId: string | null;
  code:
    | "UNUSED_SAMPLING"
    | "ORPHANED_STEP"
    | "MULTIPLE_ROOTS"
    | "DUPLICATE_API_CALL"
    | "DEEP_CHAIN"
    | "IMPLICIT_DEP_ADDED"
    | "DATA_FLOW_WARNING"
    | "STATIC_SAMPLING_PROMPT"
    | "HARDCODED_RID"
    | "TEMPLATE_AUTO_WRAPPED"
    | "AS_VAR_REWRITTEN"
    | "REQUEST_BODY_UNWRAPPED"
    | "EVENT_PARAM_REWRITTEN"
    | "PARAM_SUBFIELD_UNKNOWN"
    | "SAMPLING_SCHEMA_MISMATCH"
    | "FIELD_STRIPPED"
    | "FIELD_AUTO_SET"
    | "OUTPUT_PATH_INFERRED"
    | "OUTPUT_PATH_REF_FIXED"
    | "EVENT_PARAM_SHORTHAND"
    | "STRINGIFIED_JSON_PARSED";
  message: string;
}

export interface ComposeWorkflowResult {
  workflow: WorkflowDefinition;
  executionOrder: string[];
  summary: {
    stepCount: number;
    apiCalls: string[];
    usesSampling: boolean;
    usesElicitation: boolean;
    hasConditionals: boolean;
  };
  warnings: ComposerWarning[];
}

export class ComposerError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ComposerError";
  }
}

import type { JSONSchema7 } from "json-schema";
import { INPUT_SCHEMA_BODY_KEY } from "../parser/types.js";
import type {
  ApiCallStep,
  ConditionalStep,
  ElicitationStep,
  SamplingStep,
  TransformStep,
} from "../workflow/types.js";
import {
  ComposerError,
  type ComposerWarning,
  type ComposeStepInput,
} from "./types.js";

export function normalizeStepFields(
  steps: ComposeStepInput[],
): ComposerWarning[] {
  const warnings: ComposerWarning[] = [];
  for (const step of steps) {
    const cfg = step.config as unknown as Record<string, unknown>;
    if (cfg.type === "api_call") {
      if (cfg.as && !cfg.forEach) {
        delete cfg.as;
        warnings.push({
          stepId: step.id,
          code: "FIELD_STRIPPED",
          message: `Stripped "as" from step "${step.id}" — "as" is only used with "forEach" for iteration. Step results are accessed via steps.${step.id}`,
        });
      }
      if (cfg.forEach && !cfg.as) {
        cfg.as = `${step.id}_item`;
        warnings.push({
          stepId: step.id,
          code: "FIELD_AUTO_SET",
          message: `Auto-set as="${cfg.as}" for step "${step.id}" — "as" names the loop variable in forEach iteration`,
        });
      }
    }
  }
  return warnings;
}

export function normalizeEventParamShorthand(
  steps: ComposeStepInput[],
  params: JSONSchema7,
): ComposerWarning[] {
  const warnings: ComposerWarning[] = [];
  const paramProps = params.properties ? Object.keys(params.properties) : [];
  if (paramProps.length === 0) return warnings;

  // Reserved globally, so an out-of-scope alias reaches the scope check instead of resolving here.
  const forEachAsVars = new Set<string>();
  for (const step of steps) {
    if (step.config.type === "api_call" && (step.config as ApiCallStep).as) {
      forEachAsVars.add((step.config as ApiCallStep).as!);
    }
  }

  const templateRewriters = paramProps
    .filter((name) => !forEachAsVars.has(name))
    .map((name) => ({
      name,
      re: new RegExp(`\\{\\{(?!params\\.)${name}\\.`, "g"),
      replacement: `{{params.${name}.`,
    }));

  const jsRewriters = paramProps
    .filter((name) => !forEachAsVars.has(name))
    .map((name) => ({
      name,
      re: new RegExp(`(?<!\\.)\\b${name}\\.`, "g"),
      replacement: `params.${name}.`,
    }));

  type SubFieldRule = {
    subField: string;
    parent: string;
    templateRe: RegExp;
    templateReplacement: string;
    jsRe: RegExp;
    jsReplacement: string;
  };
  const subFieldRewriters: SubFieldRule[] = [];
  const paramPropSet = new Set(paramProps);

  for (const parentName of paramProps) {
    if (forEachAsVars.has(parentName)) continue;
    const parentSchema = params.properties![parentName] as
      | JSONSchema7
      | undefined;
    if (!parentSchema || typeof parentSchema === "boolean") continue;
    const subProps = parentSchema.properties
      ? Object.keys(parentSchema.properties)
      : [];
    for (const subName of subProps) {
      if (paramPropSet.has(subName)) continue;
      subFieldRewriters.push({
        subField: subName,
        parent: parentName,
        templateRe: new RegExp(`\\{\\{params\\.${subName}\\.`, "g"),
        templateReplacement: `{{params.${parentName}.${subName}.`,
        jsRe: new RegExp(`\\bparams\\.${subName}\\.`, "g"),
        jsReplacement: `params.${parentName}.${subName}.`,
      });
    }
  }

  function rewriteTemplate(
    stepId: string,
    value: string,
    fieldName: string,
  ): string {
    let result = value;
    for (const rule of templateRewriters) {
      const rewritten = result.replace(rule.re, rule.replacement);
      if (rewritten !== result) {
        warnings.push({
          stepId,
          code: "EVENT_PARAM_REWRITTEN",
          message: `Rewritten event param shorthand in ${fieldName}: "${rule.name}." → "params.${rule.name}."`,
        });
        result = rewritten;
      }
    }
    for (const rule of subFieldRewriters) {
      const rewritten = result.replace(
        rule.templateRe,
        rule.templateReplacement,
      );
      if (rewritten !== result) {
        warnings.push({
          stepId,
          code: "EVENT_PARAM_REWRITTEN",
          message: `Rewritten sub-field shorthand in ${fieldName}: "params.${rule.subField}." → "params.${rule.parent}.${rule.subField}."`,
        });
        result = rewritten;
      }
    }
    return result;
  }

  function rewriteJs(stepId: string, value: string, fieldName: string): string {
    const result = value;
    for (const rule of jsRewriters) {
      if (rule.re.test(result)) {
        warnings.push({
          stepId,
          code: "EVENT_PARAM_SHORTHAND",
          message: `Bare param "${rule.name}." in ${fieldName} — both "${rule.name}.x" and "params.${rule.name}.x" work at runtime`,
        });
        rule.re.lastIndex = 0;
      }
    }
    for (const rule of subFieldRewriters) {
      if (rule.jsRe.test(result)) {
        warnings.push({
          stepId,
          code: "EVENT_PARAM_SHORTHAND",
          message: `Bare sub-field "params.${rule.subField}." in ${fieldName} — both "params.${rule.subField}.x" and "params.${rule.parent}.${rule.subField}.x" work at runtime`,
        });
        rule.jsRe.lastIndex = 0;
      }
    }
    return result;
  }

  function rewriteValue(
    stepId: string,
    value: unknown,
    fieldName: string,
  ): unknown {
    if (typeof value === "string")
      return rewriteTemplate(stepId, value, fieldName);
    if (Array.isArray(value))
      return value.map((item, i) =>
        rewriteValue(stepId, item, `${fieldName}[${i}]`),
      );
    if (typeof value === "object" && value !== null) {
      const result: Record<string, unknown> = {};
      for (const [k, v] of Object.entries(value)) {
        result[k] = rewriteValue(stepId, v, `${fieldName}.${k}`);
      }
      return result;
    }
    return value;
  }

  for (const step of steps) {
    const cfg = step.config;
    switch (cfg.type) {
      case "api_call": {
        const apiCfg = cfg as ApiCallStep;
        if (apiCfg.inputMapping) {
          apiCfg.inputMapping = rewriteValue(
            step.id,
            apiCfg.inputMapping,
            "inputMapping",
          ) as Record<string, unknown>;
        }
        if (apiCfg.forEach) {
          apiCfg.forEach = rewriteTemplate(step.id, apiCfg.forEach, "forEach");
        }
        break;
      }
      case "sampling": {
        const sCfg = cfg as SamplingStep;
        sCfg.prompt = rewriteTemplate(step.id, sCfg.prompt, "prompt");
        if (sCfg.systemPrompt)
          sCfg.systemPrompt = rewriteTemplate(
            step.id,
            sCfg.systemPrompt,
            "systemPrompt",
          );
        if (sCfg.content) {
          for (const item of sCfg.content) {
            if (item.type === "text")
              item.text = rewriteTemplate(step.id, item.text, "content.text");
          }
        }
        break;
      }
      case "elicitation": {
        const eCfg = cfg as ElicitationStep;
        eCfg.message = rewriteTemplate(step.id, eCfg.message, "message");
        break;
      }
      case "conditional": {
        const cCfg = cfg as ConditionalStep;
        cCfg.condition = rewriteJs(step.id, cCfg.condition, "condition");
        break;
      }
      case "transform": {
        const tCfg = cfg as TransformStep;
        tCfg.expression = rewriteJs(step.id, tCfg.expression, "expression");
        break;
      }
    }
  }

  return warnings;
}

/** Escape for double-quoted JS string literals. */
function escapeStringLiteral(s: string): string {
  return s
    .replace(/\\/g, "\\\\")
    .replace(/"/g, '\\"')
    .replace(/\n/g, "\\n")
    .replace(/\r/g, "\\r")
    .replace(/\t/g, "\\t");
}

/** Convert {{#each}}/{{#if}} Handlebars blocks to JS expressions; throws on unsupported/nested blocks. */
function convertHandlebarsBlocks(
  input: string,
  stepId: string,
  fieldName: string,
  warnings: ComposerWarning[],
): string {
  let result = input;

  // Detect unsupported block helpers ({{#unless}}, {{#with}}, etc.)
  const unsupportedBlock = result.match(/\{\{#(?!each\b|if\b)(\w+)/);
  if (unsupportedBlock) {
    throw new ComposerError(
      `Step "${stepId}" field "${fieldName}" uses unsupported Handlebars helper "{{#${unsupportedBlock[1]}}}". ` +
        `The template engine uses {{jsExpression}} syntax. ` +
        `Use JavaScript expressions instead (e.g. array.map(), ternary operators).`,
    );
  }

  // Convert {{#each collection}}...body...{{/each}}
  const eachRe = /\{\{#each\s+([^}]+)\}\}([\s\S]*?)\{\{\/each\}\}/g;
  result = result.replace(eachRe, (_, collection: string, body: string) => {
    const col = collection.trim();

    // Check for nested blocks — bail with clear error
    if (/\{\{#(each|if)\b/.test(body)) {
      throw new ComposerError(
        `Step "${stepId}" field "${fieldName}" uses nested Handlebars blocks which cannot be auto-converted. ` +
          `Use JavaScript expressions instead. Example: ` +
          `{{${col}.map(item => item.name + ": " + item.value).join("\\n")}}`,
      );
    }

    // Static parts and dynamic {{this.X}} refs, built into a .map(...).join("").
    const parts: string[] = [];
    let lastIndex = 0;
    const refRe = /\{\{this(?:\.(\w+(?:\.\w+)*))?\}\}/g;
    let match;
    while ((match = refRe.exec(body)) !== null) {
      // Static part before this reference
      if (match.index > lastIndex) {
        parts.push(
          `"${escapeStringLiteral(body.slice(lastIndex, match.index))}"`,
        );
      }
      // Dynamic part
      const fieldPath = match[1];
      if (fieldPath) {
        parts.push(`(item.${fieldPath} ?? "")`);
      } else {
        parts.push(`(item ?? "")`);
      }
      lastIndex = match.index + match[0].length;
    }
    // Trailing static part
    if (lastIndex < body.length) {
      parts.push(`"${escapeStringLiteral(body.slice(lastIndex))}"`);
    }

    const mapBody = parts.length > 0 ? parts.join(" + ") : '""';
    const expr = `{{${col}.map(item => ${mapBody}).join("")}}`;

    // Validate the generated expression compiles
    try {
      const innerExpr = expr.slice(2, -2); // strip {{ }}
      new Function("steps", "params", `"use strict"; return (${innerExpr});`);
    } catch {
      throw new ComposerError(
        `Step "${stepId}" field "${fieldName}": auto-converted Handlebars {{#each}} failed to compile. ` +
          `Original: "${_.trim()}". Converted: "${expr}". ` +
          `Use JavaScript expressions directly instead.`,
      );
    }

    warnings.push({
      stepId,
      code: "FIELD_STRIPPED",
      message: `Auto-converted Handlebars {{#each}} to JS in ${fieldName}`,
    });
    return expr;
  });

  // Handles {{#if cond}}...{{else}}...{{/if}} and the else-less form.
  const ifElseRe =
    /\{\{#if\s+([^}]+)\}\}([\s\S]*?)\{\{else\}\}([\s\S]*?)\{\{\/if\}\}/g;
  result = result.replace(
    ifElseRe,
    (_, condition: string, thenBody: string, elseBody: string) => {
      const cond = condition.trim();
      if (
        /\{\{#(each|if)\b/.test(thenBody) ||
        /\{\{#(each|if)\b/.test(elseBody)
      ) {
        throw new ComposerError(
          `Step "${stepId}" field "${fieldName}" uses nested Handlebars blocks inside {{#if}} which cannot be auto-converted.`,
        );
      }
      const thenStr = escapeStringLiteral(thenBody);
      const elseStr = escapeStringLiteral(elseBody);
      warnings.push({
        stepId,
        code: "FIELD_STRIPPED",
        message: `Auto-converted Handlebars {{#if}}...{{else}} to JS ternary in ${fieldName}`,
      });
      return `{{${cond} ? "${thenStr}" : "${elseStr}"}}`;
    },
  );

  const ifOnlyRe = /\{\{#if\s+([^}]+)\}\}([\s\S]*?)\{\{\/if\}\}/g;
  result = result.replace(
    ifOnlyRe,
    (_, condition: string, thenBody: string) => {
      const cond = condition.trim();
      if (/\{\{#(each|if)\b/.test(thenBody)) {
        throw new ComposerError(
          `Step "${stepId}" field "${fieldName}" uses nested Handlebars blocks inside {{#if}} which cannot be auto-converted.`,
        );
      }
      const thenStr = escapeStringLiteral(thenBody);
      warnings.push({
        stepId,
        code: "FIELD_STRIPPED",
        message: `Auto-converted Handlebars {{#if}} to JS ternary in ${fieldName}`,
      });
      return `{{${cond} ? "${thenStr}" : ""}}`;
    },
  );

  return result;
}

export function normalizeTemplateFields(
  steps: ComposeStepInput[],
): ComposerWarning[] {
  const warnings: ComposerWarning[] = [];

  // An alias exists only while its owning step iterates, so track which step owns it.
  const aliasNames = new Set<string>();
  const aliasOwners = new Map<string, string[]>();
  for (const step of steps) {
    if (step.config.type === "api_call" && (step.config as ApiCallStep).as) {
      const alias = (step.config as ApiCallStep).as!;
      aliasNames.add(alias);
      const owners = aliasOwners.get(alias) ?? [];
      owners.push(step.id);
      aliasOwners.set(alias, owners);
    }
  }

  // The alias legal in the field being normalized; only the owning inputMapping sets it.
  function normalizeString(
    stepId: string,
    value: string,
    fieldName: string,
    scopedAlias?: string,
  ): string {
    // Collapse \n / \\n / \\\n → real newline (LLMs often multi-escape in JSON tool args)
    let result = value.replace(/\\+n/g, "\n").replace(/\\+t/g, "\t");

    // First: convert any Handlebars block syntax to JS expressions
    result = /\{\{#/.test(result)
      ? convertHandlebarsBlocks(result, stepId, fieldName, warnings)
      : result;

    if (/^(steps|params)\.\w+(\.\w+)*$/.test(result)) {
      const wrapped = `{{${result}}}`;
      warnings.push({
        stepId,
        code: "TEMPLATE_AUTO_WRAPPED",
        message: `Auto-wrapped bare reference in ${fieldName}: "${value}" → "${wrapped}"`,
      });
      result = wrapped;
    }

    // In scope, `{{alias.field}}` becomes `{{steps.alias.field}}`; out of scope it fails.
    for (const alias of aliasNames) {
      const asRefRe = new RegExp(
        `\\{\\{${alias}\\.(\\w+(?:\\.\\w+)*)\\}\\}`,
        "g",
      );
      if (alias === scopedAlias) {
        const rewritten = result.replace(asRefRe, `{{steps.${alias}.$1}}`);
        if (rewritten !== result) {
          warnings.push({
            stepId,
            code: "AS_VAR_REWRITTEN",
            message: `Rewritten as-variable reference in ${fieldName}: "${result}" → "${rewritten}"`,
          });
          result = rewritten;
        }
      } else if (asRefRe.test(result)) {
        const owners = aliasOwners.get(alias) ?? [];
        const ownerHint =
          owners.length > 0
            ? `step "${owners.join('", "')}"`
            : "the step that declares it";
        throw new ComposerError(
          `Step "${stepId}" references forEach alias "${alias}" in ${fieldName}, ` +
            `but "${alias}" is a loop variable that only exists inside the inputMapping of ${ownerHint}. ` +
            `A forEach alias cannot be used outside the step that declares it — the value would be empty at runtime. ` +
            `Move this logic into the loop step, or reference the completed step result via "steps.<stepId>" instead.`,
        );
      }
    }

    // Auto-strip legacy .result. from step references (Gemini training data may still emit it)
    const stripped = result.replace(/\{\{(steps\.\w+)\.result\./g, "{{$1.");
    if (stripped !== result) {
      warnings.push({
        stepId,
        code: "FIELD_STRIPPED",
        message: `Auto-stripped legacy .result from step reference in ${fieldName}: "${result}" → "${stripped}"`,
      });
      result = stripped;
    }

    return result;
  }

  function normalizeValue(
    stepId: string,
    value: unknown,
    fieldName: string,
    scopedAlias?: string,
  ): unknown {
    if (typeof value === "string") {
      // Detect stringified JSON objects/arrays and parse them back to native types
      if (/^\s*[[{]/.test(value)) {
        try {
          const parsed = JSON.parse(value);
          if (typeof parsed === "object" && parsed !== null) {
            warnings.push({
              stepId,
              code: "STRINGIFIED_JSON_PARSED",
              message: `Auto-parsed stringified JSON in ${fieldName}: "${value.length > 60 ? value.slice(0, 60) + "..." : value}"`,
            });
            return normalizeValue(stepId, parsed, fieldName, scopedAlias);
          }
        } catch {
          // Not valid JSON — leave the string as-is for template normalization.
        }
      }
      return normalizeString(stepId, value, fieldName, scopedAlias);
    }
    if (Array.isArray(value)) {
      return value.map((item, i) =>
        normalizeValue(stepId, item, `${fieldName}[${i}]`, scopedAlias),
      );
    }
    if (typeof value === "object" && value !== null) {
      const result: Record<string, unknown> = {};
      for (const [k, v] of Object.entries(value)) {
        result[k] = normalizeValue(stepId, v, `${fieldName}.${k}`, scopedAlias);
      }
      return result;
    }
    return value;
  }

  for (const step of steps) {
    const cfg = step.config;
    switch (cfg.type) {
      case "api_call": {
        const apiCfg = cfg as ApiCallStep;

        if (apiCfg.inputMapping) {
          const keys = Object.keys(apiCfg.inputMapping);
          if (
            keys.length === 1 &&
            (keys[0] === INPUT_SCHEMA_BODY_KEY || keys[0] === "body")
          ) {
            const inner = apiCfg.inputMapping[keys[0]];
            if (
              typeof inner === "object" &&
              inner !== null &&
              !Array.isArray(inner)
            ) {
              apiCfg.inputMapping = inner as Record<string, unknown>;
              warnings.push({
                stepId: step.id,
                code: "REQUEST_BODY_UNWRAPPED",
                message: `Auto-unwrapped "${keys[0]}" wrapper in inputMapping for step "${step.id}".`,
              });
            }
          }
        }

        // The loop alias is in scope only within THIS step's inputMapping.
        const ownedAlias = apiCfg.forEach ? apiCfg.as : undefined;
        if (apiCfg.inputMapping) {
          apiCfg.inputMapping = normalizeValue(
            step.id,
            apiCfg.inputMapping,
            "inputMapping",
            ownedAlias,
          ) as Record<string, unknown>;
        }
        if (apiCfg.forEach) {
          // `forEach` is evaluated before iteration, so the alias is not yet in scope.
          apiCfg.forEach = normalizeString(step.id, apiCfg.forEach, "forEach");
        }
        break;
      }
      case "sampling": {
        const sCfg = cfg as SamplingStep;
        sCfg.prompt = normalizeString(step.id, sCfg.prompt, "prompt");
        if (sCfg.systemPrompt) {
          sCfg.systemPrompt = normalizeString(
            step.id,
            sCfg.systemPrompt,
            "systemPrompt",
          );
        }
        if (sCfg.content) {
          for (const item of sCfg.content) {
            if (item.type === "text") {
              item.text = normalizeString(step.id, item.text, "content.text");
            }
          }
        }
        break;
      }
      case "elicitation": {
        const eCfg = cfg as ElicitationStep;
        eCfg.message = normalizeString(step.id, eCfg.message, "message");
        break;
      }
      // Raw JS: do not normalize templates, but do strip legacy .result references.
      case "transform": {
        const tCfg = cfg as TransformStep;
        const stripped = tCfg.expression.replace(
          /\bsteps\.(\w+)\.result\b/g,
          "steps.$1",
        );
        if (stripped !== tCfg.expression) {
          warnings.push({
            stepId: step.id,
            code: "FIELD_STRIPPED",
            message: `Auto-stripped legacy .result from transform expression: "${tCfg.expression}" → "${stripped}"`,
          });
          tCfg.expression = stripped;
        }
        break;
      }
      case "conditional": {
        const cCfg = cfg as ConditionalStep;
        const stripped = cCfg.condition.replace(
          /\bsteps\.(\w+)\.result\b/g,
          "steps.$1",
        );
        if (stripped !== cCfg.condition) {
          warnings.push({
            stepId: step.id,
            code: "FIELD_STRIPPED",
            message: `Auto-stripped legacy .result from conditional: "${cCfg.condition}" → "${stripped}"`,
          });
          cCfg.condition = stripped;
        }
        break;
      }
    }
  }

  return warnings;
}

export function flattenNestedSteps(
  steps: ComposeStepInput[],
): ComposerWarning[] {
  const warnings: ComposerWarning[] = [];
  const extracted: ComposeStepInput[] = [];

  for (const step of steps) {
    const cfg = step.config as unknown as Record<string, unknown>;
    for (const key of ["steps", "subSteps"] as const) {
      const nested = cfg[key];
      if (!Array.isArray(nested)) continue;
      for (const sub of nested) {
        if (sub && typeof sub === "object" && sub.id) {
          const subStep: ComposeStepInput = {
            id: sub.id,
            label: sub.label ?? sub.id,
            config: sub.config ?? sub,
            dependsOn: [step.id],
          };
          extracted.push(subStep);
          warnings.push({
            stepId: step.id,
            code: "IMPLICIT_DEP_ADDED",
            message: `Flattened nested step "${sub.id}" from "${step.id}.${key}" to top-level with dependsOn: ["${step.id}"]`,
          });
        }
      }
      delete cfg[key];
    }
  }

  steps.push(...extracted);
  return warnings;
}

import { OpenAPIV3 } from "openapi-types";
import type { JSONSchema7 } from "json-schema";
import { mapOpenApiSchemaToJsonSchema } from "./schema-mapper.js";
import { INPUT_SCHEMA_BODY_KEY } from "./types.js";
import type { Domain, FullEndpoint, IndexedCompactEndpoint } from "./types.js";

const AUTH_HEADER_PARAMS = new Set(["X-Auth-Token", "X-User-Id"]);
const PARAMETER_SCHEMA_LOCATIONS = ["path", "query", "header"] as const;
type ParameterSchemaLocation = (typeof PARAMETER_SCHEMA_LOCATIONS)[number];
type ResolvedMediaContent = {
  contentType: string;
  schema: OpenAPIV3.SchemaObject;
  examples?: Record<string, unknown>;
};
type ResponseContent = {
  schema?: JSONSchema7;
  examples?: Record<string, unknown>;
};

export function extractCompactEndpoints(
  api: OpenAPIV3.Document,
  domain: Domain,
): IndexedCompactEndpoint[] {
  const results: IndexedCompactEndpoint[] = [];
  if (!api.paths) return results;

  const usedIds = new Set<string>();

  for (const [path, pathItem] of Object.entries(api.paths)) {
    if (!pathItem) continue;

    for (const method of Object.values(OpenAPIV3.HttpMethods)) {
      const safeMethod = method as OpenAPIV3.HttpMethods;
      const operation = pathItem[safeMethod];
      if (!operation) continue;

      const operationId = deduplicateId(
        sanitizeOperationId(operation.operationId, method, path),
        usedIds,
      );

      results.push({
        operationId,
        summary:
          operation.summary ||
          operation.description?.slice(0, 80) ||
          `${method.toUpperCase()} ${path}`,
        domain,
        path,
        method,
      });
    }
  }

  return results;
}

export function extractFullEndpoints(
  api: OpenAPIV3.Document,
  domain: Domain,
  filterIds?: Set<string>,
  maxDepth?: number,
): FullEndpoint[] {
  const results: FullEndpoint[] = [];
  if (!api.paths) return results;

  const globalSecurity = api.security || [];
  const usedIds = new Set<string>();

  for (const [path, pathItem] of Object.entries(api.paths)) {
    if (!pathItem) continue;

    for (const method of Object.values(OpenAPIV3.HttpMethods)) {
      const safeMethod = method as OpenAPIV3.HttpMethods;
      const operation = pathItem[safeMethod];
      if (!operation) continue;

      const operationId = deduplicateId(
        sanitizeOperationId(operation.operationId, method, path),
        usedIds,
      );

      if (filterIds && !filterIds.has(operationId)) continue;

      results.push(
        buildFullEndpoint(
          domain,
          operationId,
          path,
          method,
          pathItem,
          operation,
          globalSecurity,
          maxDepth,
        ),
      );
    }
  }

  return results;
}

export function extractEndpointByLocation(
  api: OpenAPIV3.Document,
  domain: Domain,
  operationId: string,
  path: string,
  method: string,
  maxDepth?: number,
): FullEndpoint | null {
  const pathItem = api.paths?.[path];
  if (!pathItem) return null;

  const operation = pathItem[method as OpenAPIV3.HttpMethods];
  if (!operation) return null;

  return buildFullEndpoint(
    domain,
    operationId,
    path,
    method,
    pathItem,
    operation,
    api.security || [],
    maxDepth,
  );
}

function buildFullEndpoint(
  domain: Domain,
  operationId: string,
  path: string,
  method: string,
  pathItem: OpenAPIV3.PathItemObject,
  operation: OpenAPIV3.OperationObject,
  globalSecurity: OpenAPIV3.SecurityRequirementObject[],
  maxDepth?: number,
): FullEndpoint {
  const allParams = mergeParameters(
    toParameterObjects(pathItem.parameters),
    toParameterObjects(operation.parameters),
  );

  let requestBody: FullEndpoint["requestBody"];
  let requestBodySchema: JSONSchema7 | undefined;
  let requestBodyRequired = false;
  let requestExamples: Record<string, unknown> | undefined;
  if (operation.requestBody && !("$ref" in operation.requestBody)) {
    const rb = operation.requestBody;
    const resolved = resolveRequestBodyContent(rb);
    if (resolved) {
      requestBodySchema = mapOpenApiSchemaToJsonSchema(
        resolved.schema,
        undefined,
        maxDepth,
      );
      requestBodyRequired = rb.required ?? false;
      requestBody = {
        contentType: resolved.contentType,
        schema: requestBodySchema,
        required: requestBodyRequired,
      };
      requestExamples = resolved.examples;
    }
  }

  const { inputSchema, parameterSchemas } = buildInputSchemas(
    allParams,
    requestBodySchema,
    requestBodyRequired,
    maxDepth,
  );

  const successResponse = extractSuccessResponse(operation.responses, maxDepth);
  const errorResponses = extractErrorResponses(operation.responses, maxDepth);
  const security =
    operation.security === undefined
      ? globalSecurity
      : operation.security || [];

  const summary =
    operation.summary ||
    operation.description?.slice(0, 80) ||
    `${method.toUpperCase()} ${path}`;

  const ep: FullEndpoint = {
    operationId,
    method: method.toUpperCase(),
    path,
    summary,
    description: operation.description || summary,
    domain,
    parameters: allParams,
    requestBody,
    security,
    inputSchema,
    parameterSchemas,
  };
  if (successResponse.schema) ep.responseSchema = successResponse.schema;
  if (operation.deprecated) ep.deprecated = true;
  if (requestExamples) ep.requestExamples = requestExamples;
  if (successResponse.examples) ep.responseExamples = successResponse.examples;
  if (errorResponses) ep.errorResponses = errorResponses;
  return ep;
}

function sanitizeOperationId(
  raw: string | undefined,
  method: string,
  path: string,
): string {
  const base = raw || `${method}_${path.replace(/[^a-zA-Z0-9]/g, "_")}`;
  return base.replace(/\./g, "_").replace(/[^a-z0-9_-]/gi, "_");
}

function deduplicateId(id: string, usedIds: Set<string>): string {
  if (!usedIds.has(id)) {
    usedIds.add(id);
    return id;
  }
  let counter = 1;
  while (usedIds.has(`${id}_${counter}`)) counter++;
  const unique = `${id}_${counter}`;
  usedIds.add(unique);
  return unique;
}

function mergeParameters(
  pathParams?: OpenAPIV3.ParameterObject[],
  opParams?: OpenAPIV3.ParameterObject[],
): OpenAPIV3.ParameterObject[] {
  const path = pathParams || [];
  const op = opParams || [];
  const merged: OpenAPIV3.ParameterObject[] = [];

  path.concat(op).forEach((param) => {
    const idx = merged.findIndex(
      (p) => p.name === param.name && p.in === param.in,
    );
    if (idx >= 0) {
      merged[idx] = param;
    } else {
      merged.push(param);
    }
  });

  return merged;
}

function toParameterObjects(
  params?: (OpenAPIV3.ParameterObject | OpenAPIV3.ReferenceObject)[],
): OpenAPIV3.ParameterObject[] | undefined {
  if (!params) return undefined;

  return params.filter((param): param is OpenAPIV3.ParameterObject => {
    return !("$ref" in param);
  });
}

function isParameterSchemaLocation(
  location: OpenAPIV3.ParameterObject["in"],
): location is ParameterSchemaLocation {
  return PARAMETER_SCHEMA_LOCATIONS.includes(
    location as ParameterSchemaLocation,
  );
}

function buildObjectSchema(
  properties: Record<string, JSONSchema7>,
  required: string[],
): JSONSchema7 | undefined {
  if (Object.keys(properties).length === 0) return undefined;

  return {
    type: "object",
    properties,
    ...(required.length > 0 && { required }),
  };
}

function buildInputSchemas(
  params: OpenAPIV3.ParameterObject[],
  requestBodySchema?: JSONSchema7,
  requestBodyRequired = false,
  maxDepth?: number,
): {
  inputSchema: JSONSchema7;
  parameterSchemas: FullEndpoint["parameterSchemas"];
} {
  const inputProperties: Record<string, JSONSchema7> = {};
  const inputRequired: string[] = [];
  const grouped = Object.fromEntries(
    PARAMETER_SCHEMA_LOCATIONS.map((location) => [
      location,
      {
        properties: {} as Record<string, JSONSchema7>,
        required: [] as string[],
      },
    ]),
  ) as Record<
    ParameterSchemaLocation,
    { properties: Record<string, JSONSchema7>; required: string[] }
  >;

  for (const param of params) {
    if (!param.name || !param.schema) continue;
    if (param.in === "header" && AUTH_HEADER_PARAMS.has(param.name)) continue;

    const paramSchema = mapOpenApiSchemaToJsonSchema(
      param.schema as OpenAPIV3.SchemaObject,
      undefined,
      maxDepth,
    );
    if (param.description && typeof paramSchema === "object") {
      paramSchema.description = param.description;
    }
    if (param.example !== undefined && typeof paramSchema === "object") {
      paramSchema.examples = [param.example];
    }

    inputProperties[param.name] = paramSchema;
    if (param.required) inputRequired.push(param.name);

    if (isParameterSchemaLocation(param.in)) {
      grouped[param.in].properties[param.name] = paramSchema;
      if (param.required) grouped[param.in].required.push(param.name);
    }
  }

  if (requestBodySchema) {
    inputProperties[INPUT_SCHEMA_BODY_KEY] = requestBodySchema;
    if (requestBodyRequired) inputRequired.push(INPUT_SCHEMA_BODY_KEY);
  }

  const parameterSchemas: FullEndpoint["parameterSchemas"] = {};
  for (const location of PARAMETER_SCHEMA_LOCATIONS) {
    const schema = buildObjectSchema(
      grouped[location].properties,
      grouped[location].required,
    );
    if (schema) parameterSchemas[location] = schema;
  }

  const inputSchema: JSONSchema7 = {
    type: "object",
    properties: inputProperties,
    ...(inputRequired.length > 0 && { required: inputRequired }),
  };

  return { inputSchema, parameterSchemas };
}

const CONTENT_TYPE_PRIORITY = [
  "application/json",
  "multipart/form-data",
] as const;

function resolveRequestBodyContent(
  rb: OpenAPIV3.RequestBodyObject,
): ResolvedMediaContent | undefined {
  for (const contentType of CONTENT_TYPE_PRIORITY) {
    const media = rb.content?.[contentType];
    if (media?.schema) {
      return {
        contentType,
        schema: media.schema as OpenAPIV3.SchemaObject,
        examples: extractMediaExamples(media),
      };
    }
  }

  if (rb.content) {
    for (const [contentType, media] of Object.entries(rb.content)) {
      if (media?.schema) {
        return {
          contentType,
          schema: media.schema as OpenAPIV3.SchemaObject,
          examples: extractMediaExamples(media),
        };
      }
    }
  }

  return undefined;
}

function extractSuccessResponse(
  responses: OpenAPIV3.ResponsesObject,
  maxDepth?: number,
): ResponseContent {
  const successCodes = Object.keys(responses)
    .filter((code) => /^2\d{2}$/.test(code))
    .sort();

  for (const code of successCodes) {
    const resp = responses[code];
    if (!resp || "$ref" in resp) continue;

    const media = resp.content?.["application/json"];
    if (!media?.schema) continue;

    return {
      schema: mapOpenApiSchemaToJsonSchema(
        media.schema as OpenAPIV3.SchemaObject,
        undefined,
        maxDepth,
      ),
      examples: extractMediaExamples(media),
    };
  }

  return {};
}

function extractErrorResponses(
  responses: OpenAPIV3.ResponsesObject,
  maxDepth?: number,
): FullEndpoint["errorResponses"] | undefined {
  const errors: NonNullable<FullEndpoint["errorResponses"]> = {};

  for (const code of Object.keys(responses).sort()) {
    if (!/^[45]\d{2}$/.test(code)) continue;

    const resp = responses[code];
    if (!resp || "$ref" in resp) continue;

    const error: { description: string; schema?: JSONSchema7 } = {
      description: resp.description,
    };
    const media = resp.content?.["application/json"];
    if (media?.schema) {
      error.schema = mapOpenApiSchemaToJsonSchema(
        media.schema as OpenAPIV3.SchemaObject,
        undefined,
        maxDepth,
      );
    }
    errors[code] = error;
  }

  return Object.keys(errors).length > 0 ? errors : undefined;
}

function extractMediaExamples(
  media: OpenAPIV3.MediaTypeObject,
): Record<string, unknown> | undefined {
  const examples: Record<string, unknown> = {};

  if (media.examples) {
    Object.assign(examples, media.examples);
  }

  if (media.example !== undefined) {
    const key = examples.default === undefined ? "default" : "example";
    examples[key] = media.example;
  }

  return Object.keys(examples).length > 0 ? examples : undefined;
}

import type { WorkflowDefinition } from "../workflow/types.js";

/**
 * Read rules are category-wide, privileged rules per-operation, and every match unions in.
 * `[._-]` matches both `channels.create` and `post-api-v1-channels_create`.
 */
const OPERATION_PERMISSION_MAP: Array<{
  pattern: RegExp;
  permissions: string[];
}> = [
  // Read tier — matched by any operation in the family.
  {
    pattern: /channels[._-]/,
    permissions: ["view-c-room", "view-joined-room"],
  },
  { pattern: /groups[._-]/, permissions: ["view-p-room", "view-joined-room"] },
  {
    pattern: /im[._-]|dm[._-]/,
    permissions: ["view-d-room", "view-joined-room"],
  },
  {
    pattern: /rooms[._-]/,
    permissions: ["view-c-room", "view-p-room", "view-joined-room"],
  },
  { pattern: /users[._-]/, permissions: ["view-full-other-user-info"] },

  // Privileged tier — matched only by the specific operation.
  { pattern: /channels[._-]create/, permissions: ["create-c"] },
  { pattern: /groups[._-]create/, permissions: ["create-p"] },
  { pattern: /(im|dm)[._-](create|open)/, permissions: ["create-d"] },
  {
    pattern:
      /(channels|groups)[._-](rename|setTopic|setAnnouncement|setDescription|setPurpose|setCustomFields|setDefault|setType|setJoinCode)/,
    permissions: ["edit-room"],
  },
  {
    pattern: /(channels|groups)[._-]setReadOnly/,
    permissions: ["set-readonly", "post-readonly"],
  },
  // The separator class before the verb keeps `archive` off `unarchive`.
  { pattern: /(channels|groups)[._-]archive/, permissions: ["archive-room"] },
  {
    pattern: /(channels|groups)[._-]unarchive/,
    permissions: ["unarchive-room"],
  },
  {
    pattern: /(channels|groups|rooms)[._-]cleanHistory/,
    permissions: ["clean-channel-history"],
  },
  { pattern: /channels[._-]delete/, permissions: ["delete-c"] },
  { pattern: /groups[._-]delete/, permissions: ["delete-p"] },
  {
    pattern: /(channels|groups)[._-](invite|addAll|addOwner|addModerator)/,
    permissions: [
      "add-user-to-joined-room",
      "add-user-to-any-c-room",
      "add-user-to-any-p-room",
    ],
  },
  {
    pattern: /(channels|groups)[._-]kick/,
    permissions: ["remove-user"],
  },
  { pattern: /rooms[._-](muteUser|unmuteUser)/, permissions: ["mute-user"] },
  // `postMessage` resolves `@user` into a DM, hence `create-d`; mentions cover @here/@all.
  {
    pattern: /chat[._-](postMessage|sendMessage)/,
    permissions: ["create-d", "post-readonly", "mention-here", "mention-all"],
  },
  { pattern: /chat[._-]update/, permissions: ["edit-message"] },
  { pattern: /chat[._-]delete/, permissions: ["delete-message"] },
  // Starring is per-user, so it needs no permission of its own.
  { pattern: /chat[._-](un)?[Pp]in/, permissions: ["pin-message"] },
  {
    pattern: /users[._-](create|update|delete|setActiveStatus)/,
    permissions: [
      "create-user",
      "edit-other-user-info",
      "edit-other-user-active-status",
    ],
  },
  { pattern: /[Dd]iscussions[._-]create/, permissions: ["start-discussion"] },
  {
    pattern: /roles[._-]|permissions[._-]/,
    permissions: ["access-permissions"],
  },
  { pattern: /emoji[._-]custom/, permissions: ["manage-emoji"] },
];

/** Permissions every generated Rocket.Chat server needs, regardless of workflow. */
const BASE_BOT_PERMISSIONS = [
  "create-personal-access-tokens",
  "view-outside-room",
];

/** Permissions the server's Rocket.Chat account needs for the endpoints it calls. */
export function deriveRequiredPermissions(
  workflows: WorkflowDefinition[],
): string[] {
  const perms = new Set<string>(BASE_BOT_PERMISSIONS);

  const allOps = new Set<string>();
  for (const wf of workflows) {
    for (const operationId of wf.requiredEndpoints) allOps.add(operationId);
  }

  for (const operationId of allOps) {
    for (const rule of OPERATION_PERMISSION_MAP) {
      if (rule.pattern.test(operationId)) {
        for (const permission of rule.permissions) perms.add(permission);
      }
    }
  }

  return [...perms];
}

import { parse } from "acorn";

const SAFE_METHODS = new Set([
  "at",
  "charAt",
  "charCodeAt",
  "codePointAt",
  "concat",
  "copyWithin",
  "endsWith",
  "entries",
  "every",
  "filter",
  "find",
  "findIndex",
  "flat",
  "flatMap",
  "forEach",
  "includes",
  "indexOf",
  "join",
  "keys",
  "lastIndexOf",
  "map",
  "match",
  "matchAll",
  "normalize",
  "padEnd",
  "padStart",
  "pop",
  "push",
  "reduce",
  "repeat",
  "replace",
  "replaceAll",
  "reverse",
  "search",
  "shift",
  "slice",
  "some",
  "sort",
  "split",
  "startsWith",
  "substring",
  "substr",
  "toJSON",
  "toLowerCase",
  "toString",
  "toUpperCase",
  "trim",
  "trimEnd",
  "trimStart",
  "unshift",
  "valueOf",
  "values",
]);

const SAFE_STATIC_CALLS = new Map([
  ["Array", new Set(["isArray", "from"])],
  ["Date", new Set(["now", "parse"])],
  ["JSON", new Set(["parse", "stringify"])],
  ["Math", new Set(Object.getOwnPropertyNames(Math))],
  [
    "Number",
    new Set(["isFinite", "isInteger", "isNaN", "parseFloat", "parseInt"]),
  ],
  ["Object", new Set(["entries", "fromEntries", "keys", "values"])],
  ["String", new Set(["raw"])],
]);

const SAFE_IDENTIFIER_CALLS = new Set([
  "Boolean",
  "Number",
  "String",
  "decodeURIComponent",
  "encodeURIComponent",
  "isFinite",
  "isNaN",
  "parseFloat",
  "parseInt",
]);

const ALLOWED_GLOBALS = new Set([
  ...SAFE_IDENTIFIER_CALLS,
  ...SAFE_STATIC_CALLS.keys(),
  "undefined",
  "null",
  "true",
  "false",
  "NaN",
  "Infinity",
]);

const BLOCKED_PROPERTIES = new Set(["__proto__", "constructor", "prototype"]);

/** Explicit bound so deep nesting fails predictably, not with a platform-dependent overflow. */
const MAX_AST_DEPTH = 500;

// eslint-disable-next-line @typescript-eslint/no-explicit-any -- Acorn nodes are inspected structurally by node type.
type Node = Record<string, any>;

/** An explicit work stack, so the guard itself cannot overflow. */
function assertBoundedDepth(ast: Node): void {
  const stack: Array<{ node: unknown; depth: number }> = [
    { node: ast, depth: 0 },
  ];
  while (stack.length > 0) {
    const { node, depth } = stack.pop()!;
    if (depth > MAX_AST_DEPTH) {
      reject(`expression nesting too deep (max ${MAX_AST_DEPTH})`);
    }
    if (!node || typeof node !== "object") continue;
    for (const key of Object.keys(node as Record<string, unknown>)) {
      if (key === "type" || key === "start" || key === "end") continue;
      const child = (node as Record<string, unknown>)[key];
      if (Array.isArray(child)) {
        for (const item of child) {
          if (item && typeof item === "object")
            stack.push({ node: item, depth: depth + 1 });
        }
      } else if (child && typeof child === "object") {
        stack.push({ node: child, depth: depth + 1 });
      }
    }
  }
}

export function validateSafeExpression(
  expr: string,
  context: string,
  additionalIdentifiers?: Iterable<string>,
): void {
  const trimmed = expr.trim();
  if (!trimmed) return;

  try {
    const ast = parseAsExpression(trimmed) ?? parseAsProgram(trimmed);
    assertBoundedDepth(ast);
    const scope = new Scope(additionalIdentifiers);
    validateNode(ast, scope);
  } catch (err) {
    const detail = err instanceof Error ? err.message : String(err);
    throw new Error(
      `Unsafe ${context} expression rejected: "${expr}". ${detail}`,
      { cause: err },
    );
  }
}

export function autoReturnExpression(expr: string): string {
  if (isValidSyntax(expr)) return expr;

  const trimmed = expr.trimEnd();
  if (!trimmed.endsWith("}")) return expr;

  let depth = 0;
  let objStart = -1;
  for (let i = trimmed.length - 1; i >= 0; i--) {
    if (trimmed[i] === "}") depth++;
    else if (trimmed[i] === "{") {
      depth--;
      if (depth === 0) {
        objStart = i;
        break;
      }
    }
  }
  if (objStart <= 0) return expr;

  const before = trimmed.substring(0, objStart).trimEnd();
  if (before.endsWith(")") || before.endsWith("else")) return expr;

  const objPart = trimmed.substring(objStart);
  const stmtPart = before.endsWith(";") ? before : before + ";";
  const candidate = `${stmtPart} return (${objPart});`;

  if (isValidFunctionBody(candidate)) return candidate;
  return expr;
}

function isValidSyntax(code: string): boolean {
  try {
    parse(code, { ecmaVersion: "latest", sourceType: "script" });
    return true;
  } catch {
    return false;
  }
}

function isValidFunctionBody(code: string): boolean {
  try {
    parse(`function __check__() { ${code} }`, {
      ecmaVersion: "latest",
      sourceType: "script",
    });
    return true;
  } catch {
    return false;
  }
}

function parseAsExpression(expr: string): Node | null {
  try {
    const program = parse(`(${expr});`, {
      ecmaVersion: "latest",
      sourceType: "script",
    }) as Node;
    return program;
  } catch {
    return null;
  }
}

function parseAsProgram(expr: string): Node {
  try {
    return parse(expr, {
      ecmaVersion: "latest",
      sourceType: "script",
    }) as Node;
  } catch {
    const program = parse(`function __workflowExpression__() { ${expr} }`, {
      ecmaVersion: "latest",
      sourceType: "script",
    }) as Node;
    return program.body[0].body;
  }
}

class Scope {
  private readonly frames: Array<Set<string>>;

  constructor(additionalIdentifiers?: Iterable<string>) {
    const base = new Set(["params", "steps"]);
    if (additionalIdentifiers) {
      for (const id of additionalIdentifiers) base.add(id);
    }
    this.frames = [base];
  }

  has(name: string): boolean {
    return this.frames.some((frame) => frame.has(name));
  }

  declare(name: string): void {
    this.frames[this.frames.length - 1].add(name);
  }

  child<T>(names: string[], fn: () => T): T {
    this.frames.push(new Set(names));
    try {
      return fn();
    } finally {
      this.frames.pop();
    }
  }
}

function validateNode(node: Node | null | undefined, scope: Scope): void {
  if (!node) return;

  switch (node.type) {
    case "ArrayExpression":
      validateList(node.elements, scope);
      return;
    case "ArrowFunctionExpression":
      validateArrowFunction(node, scope);
      return;
    case "AssignmentExpression":
      validateAssignment(node, scope);
      return;
    case "BinaryExpression":
    case "LogicalExpression":
      validateNode(node.left, scope);
      validateNode(node.right, scope);
      return;
    case "BlockStatement":
      scope.child([], () => validateList(node.body, scope));
      return;
    case "CallExpression":
      validateCallExpression(node, scope);
      return;
    case "ChainExpression":
      validateNode(node.expression, scope);
      return;
    case "ConditionalExpression":
      validateNode(node.test, scope);
      validateNode(node.consequent, scope);
      validateNode(node.alternate, scope);
      return;
    case "ExpressionStatement":
      validateNode(node.expression, scope);
      return;
    case "Identifier":
      validateIdentifier(node.name, scope);
      return;
    case "IfStatement":
      validateNode(node.test, scope);
      validateNode(node.consequent, scope);
      validateNode(node.alternate, scope);
      return;
    case "Literal":
      return;
    case "MemberExpression":
      validateMemberExpression(node, scope);
      return;
    case "ObjectExpression":
      validateList(node.properties, scope);
      return;
    case "Property":
      if (node.computed) validateNode(node.key, scope);
      validateNode(node.value, scope);
      return;
    case "Program":
      validateList(node.body, scope);
      return;
    case "ReturnStatement":
      validateNode(node.argument, scope);
      return;
    case "TemplateElement":
      return;
    case "TemplateLiteral":
      validateList(node.expressions, scope);
      return;
    case "SpreadElement":
    case "UnaryExpression":
      validateNode(node.argument, scope);
      return;
    case "UpdateExpression":
      validateMutationTarget(node.argument, scope);
      return;
    case "VariableDeclaration":
      if (node.kind === "var") reject("var declarations are not allowed");
      validateList(node.declarations, scope);
      return;
    case "VariableDeclarator":
      declarePattern(node.id, scope);
      validateNode(node.init, scope);
      return;
    default:
      reject(`${node.type} is not allowed`);
  }
}

function validateList(
  nodes: Array<Node | null | undefined>,
  scope: Scope,
): void {
  for (const child of nodes) validateNode(child, scope);
}

function validateArrowFunction(node: Node, scope: Scope): void {
  const names = node.params.flatMap(patternNames);
  scope.child(names, () => validateNode(node.body, scope));
}

function validateAssignment(node: Node, scope: Scope): void {
  validateMutationTarget(node.left, scope);
  validateNode(node.right, scope);
}

function validateCallExpression(node: Node, scope: Scope): void {
  if (!isSafeCallee(node.callee, scope)) {
    reject("only approved function and method calls are allowed");
  }
  validateList(node.arguments, scope);
}

function isSafeCallee(callee: Node, scope: Scope): boolean {
  if (callee.type === "ChainExpression") {
    return isSafeCallee(callee.expression, scope);
  }

  if (callee.type === "Identifier") {
    validateIdentifier(callee.name, scope);
    return SAFE_IDENTIFIER_CALLS.has(callee.name);
  }

  if (callee.type !== "MemberExpression") return false;

  const property = propertyName(callee);
  if (!property || BLOCKED_PROPERTIES.has(property)) return false;

  const root = memberRootName(callee);
  if (root) {
    validateIdentifier(root, scope);
    const staticMethods = SAFE_STATIC_CALLS.get(root);
    if (staticMethods) return staticMethods.has(property);
  }

  validateMemberExpression(callee, scope);
  return SAFE_METHODS.has(property);
}

function validateMemberExpression(node: Node, scope: Scope): void {
  const property = propertyName(node);
  if (property && BLOCKED_PROPERTIES.has(property)) {
    reject(`property "${property}" is not allowed`);
  }
  if (node.computed && property === null) {
    reject(
      "computed property access with dynamic keys is not allowed — use dot notation or a literal key",
    );
  }
  validateNode(node.object, scope);
  if (node.computed) validateNode(node.property, scope);
}

function validateIdentifier(name: string, scope: Scope): void {
  if (scope.has(name)) return;
  if (ALLOWED_GLOBALS.has(name)) return;
  reject(`identifier "${name}" is not allowed`);
}

function validateMutationTarget(node: Node, scope: Scope): void {
  if (node.type === "Identifier") {
    if (!scope.has(node.name)) {
      reject(
        `assignment to undeclared identifier "${node.name}" is not allowed`,
      );
    }
    validateIdentifier(node.name, scope);
    return;
  }

  if (node.type === "MemberExpression") {
    const root = memberRootName(node);
    if (!root || !scope.has(root) || root === "params" || root === "steps") {
      reject("only local variables can be mutated");
    }
    validateMemberExpression(node, scope);
    return;
  }

  reject(`${node.type} cannot be assigned to`);
}

function declarePattern(node: Node, scope: Scope): void {
  for (const name of patternNames(node)) scope.declare(name);
}

const RESERVED_SCOPE_NAMES = new Set(["params", "steps"]);

function patternNames(node: Node): string[] {
  switch (node.type) {
    case "Identifier":
      if (RESERVED_SCOPE_NAMES.has(node.name)) {
        reject(
          `cannot declare variable "${node.name}" — it shadows a reserved name`,
        );
      }
      return [node.name];
    case "ArrayPattern":
      return node.elements.flatMap((item: Node | null) =>
        item ? patternNames(item) : [],
      );
    case "AssignmentPattern":
      return patternNames(node.left);
    case "ObjectPattern":
      return node.properties.flatMap((property: Node) =>
        patternNames(property.value ?? property.argument),
      );
    case "RestElement":
      return patternNames(node.argument);
    default:
      reject(`${node.type} is not allowed in binding patterns`);
  }
}

function memberRootName(node: Node): string | null {
  let current = node;
  while (
    current.type === "MemberExpression" ||
    current.type === "ChainExpression"
  ) {
    current =
      current.type === "ChainExpression" ? current.expression : current.object;
  }
  return current.type === "Identifier" ? current.name : null;
}

function propertyName(node: Node): string | null {
  if (node.computed) {
    return node.property.type === "Literal"
      ? String(node.property.value)
      : null;
  }
  return node.property.type === "Identifier" ? node.property.name : null;
}

function reject(message: string): never {
  throw new Error(message);
}

import type { ApiCallStep, WorkflowStep } from "./types.js";
import type {
  EndpointInfo,
  ExecutionState,
  WorkflowClient,
} from "./executor.js";
import { evaluateExpression, resolveMapping } from "./templates.js";

const DEFAULT_FOREACH_CONCURRENCY = 5;
const MAX_RESPONSE_BYTES = 10 * 1024 * 1024; // 10 MB

/** Walk a dotted path into a parsed value, returning null on any miss. */
export function extractPath(value: unknown, path: string): unknown {
  return path.split(".").reduce<unknown>((acc, key) => {
    if (acc != null && typeof acc === "object" && !Array.isArray(acc)) {
      return (acc as Record<string, unknown>)[key] ?? null;
    }
    return null;
  }, value);
}

/** Consumed keys are removed so they are not resent; a placeholder with no value throws. */
function substitutePathParams(
  path: string,
  payload: Record<string, unknown>,
  operationId: string,
): string {
  return path.replace(/\{([^}]+)\}/g, (_match, rawName: string) => {
    const name = rawName.trim();
    const value = payload[name];
    if (value === undefined || value === null || value === "") {
      throw new Error(
        `API call "${operationId}" is missing required path parameter "${name}".`,
      );
    }
    delete payload[name];
    return typeof value === "object"
      ? encodeURIComponent(JSON.stringify(value))
      : encodeURIComponent(String(value));
  });
}

function buildGetUrl(path: string, payload: Record<string, unknown>): string {
  const search = new URLSearchParams();
  for (const [k, v] of Object.entries(payload)) {
    search.append(
      k,
      typeof v === "object" && v !== null ? JSON.stringify(v) : String(v ?? ""),
    );
  }
  const query = search.toString();
  return query ? `${path}?${query}` : path;
}

/** With no declared locations (offline) the verb decides: GET -> query string, else body. */
function splitByLocation(
  endpoint: EndpointInfo,
  payload: Record<string, unknown>,
): {
  headers: Record<string, string>;
  query: Record<string, unknown>;
  body: Record<string, unknown>;
} {
  const headers: Record<string, string> = {};
  const query: Record<string, unknown> = {};
  const body: Record<string, unknown> = {};

  const declaredQuery = new Set(endpoint.queryParams ?? []);
  const declaredHeader = new Set(endpoint.headerParams ?? []);
  const isGet = endpoint.method.toUpperCase() === "GET";

  for (const [key, value] of Object.entries(payload)) {
    if (declaredHeader.has(key)) {
      // Headers are a flat string channel; objects are serialized so a mistake is visible.
      if (value !== undefined && value !== null) {
        headers[key] =
          typeof value === "object" ? JSON.stringify(value) : String(value);
      }
      continue;
    }
    if (declaredQuery.has(key)) {
      query[key] = value;
      continue;
    }
    // Undeclared: fall back to the verb.
    if (isGet) query[key] = value;
    else body[key] = value;
  }

  return { headers, query, body };
}

/** An absent source drops an optional param; a source that exists but resolved empty throws. */
function pruneEmptyParams(
  step: ApiCallStep,
  payload: Record<string, unknown>,
  state: ExecutionState,
): void {
  for (const [key, raw] of Object.entries(step.inputMapping)) {
    if (typeof raw !== "string" || !raw.includes("{{")) continue;
    const resolved = payload[key];
    if (resolved !== "" && resolved !== undefined && resolved !== null)
      continue;

    const paramMatch = raw.match(/\{\{\s*params\.(\w+)/);
    const stepMatch = raw.match(/\{\{\s*steps\.(\w+)/);
    if (paramMatch && !(paramMatch[1] in state.params)) {
      delete payload[key];
    } else if (stepMatch && !(stepMatch[1] in state.steps)) {
      delete payload[key];
    } else {
      throw new Error(
        `Parameter "${key}" resolved to empty (template: ${raw}).`,
      );
    }
  }
}

async function callOnce(
  step: ApiCallStep,
  payload: Record<string, unknown>,
  state: ExecutionState,
  client: WorkflowClient,
  endpoints: Record<string, EndpointInfo>,
): Promise<unknown> {
  const endpoint: EndpointInfo | undefined = endpoints[step.operationId];
  if (!endpoint) {
    throw new Error(
      `No endpoint registered for operationId "${step.operationId}". ` +
        `The workflow references an operationId that is not in the endpoint map.`,
    );
  }
  const method = endpoint.method.toUpperCase();
  const rawPath = endpoint.path;

  pruneEmptyParams(step, payload, state);

  const path = substitutePathParams(rawPath, payload, step.operationId);

  if (method === "GET") {
    // Decode JSON-looking string values so they ride along as query params.
    for (const [k, v] of Object.entries(payload)) {
      if (typeof v === "string" && /^[[{]/.test(v)) {
        try {
          payload[k] = JSON.parse(v);
        } catch {
          // keep as string
        }
      }
    }
  }

  // Header params have nowhere else to go: by-verb routing put them in the body.
  const { headers, query, body } = splitByLocation(endpoint, payload);

  const hasQuery = Object.keys(query).length > 0;
  const sendsBody = method !== "GET" && Object.keys(body).length > 0;

  const response = await client.request(
    method,
    hasQuery ? buildGetUrl(path, query) : path,
    {
      // Anything the spec has not marked credential-free stays authenticated.
      auth: endpoint.auth !== false,
      ...(sendsBody ? { body } : {}),
      ...(Object.keys(headers).length > 0 ? { headers } : {}),
    },
  );

  if (!response.ok) {
    const detail =
      typeof response.data === "string"
        ? response.data
        : JSON.stringify(response.data);
    throw new Error(
      `API call "${step.operationId}" failed (status ${response.status}): ${detail}`,
    );
  }

  if (
    typeof response.data === "string" &&
    response.data.length > MAX_RESPONSE_BYTES
  ) {
    throw new Error(
      `API response for "${step.operationId}" exceeds the 10 MB limit.`,
    );
  }

  return step.outputPath
    ? extractPath(response.data, step.outputPath)
    : response.data;
}

export async function executeApiCall(
  step: WorkflowStep,
  state: ExecutionState,
  client: WorkflowClient,
  endpoints: Record<string, EndpointInfo>,
  maxForEachIterations: number,
): Promise<void> {
  const config = step.config as ApiCallStep;

  if (config.forEach && config.as) {
    const itemVar = config.as;
    // The composer stores forEach bare; residual `{{ }}` is tolerated defensively.
    const expr = config.forEach.trim();
    const cleaned =
      expr.startsWith("{{") && expr.endsWith("}}")
        ? expr.slice(2, -2).trim()
        : expr;
    let raw: unknown;
    try {
      raw = evaluateExpression(cleaned, state.params, state.steps);
    } catch {
      raw = [];
    }
    const collection = Array.isArray(raw) ? raw : [];
    if (collection.length > maxForEachIterations) {
      throw new Error(
        `Step "${step.id}" forEach has ${collection.length} items, ` +
          `exceeding the maximum of ${maxForEachIterations}.`,
      );
    }

    const results: unknown[] = new Array(collection.length).fill(null);
    const failures: Array<{ index: number; error: string }> = [];
    for (let i = 0; i < collection.length; i += DEFAULT_FOREACH_CONCURRENCY) {
      const slice = collection.slice(i, i + DEFAULT_FOREACH_CONCURRENCY);
      const settled = await Promise.allSettled(
        slice.map((item) => {
          const locals = { [itemVar]: item };
          const augmentedSteps = { ...state.steps, [itemVar]: item };
          const payload = resolveMapping(
            config.inputMapping,
            state.params,
            augmentedSteps,
            locals,
          );
          return callOnce(config, payload, state, client, endpoints);
        }),
      );
      for (let j = 0; j < settled.length; j++) {
        const r = settled[j];
        const index = i + j;
        if (r.status === "fulfilled") {
          results[index] = r.value;
        } else {
          failures.push({
            index,
            error:
              r.reason instanceof Error ? r.reason.message : String(r.reason),
          });
        }
      }
    }

    if (failures.length > 0) {
      const summary = failures
        .map((f) => `item ${f.index}: ${f.error}`)
        .join("; ");
      // Default: a bulk action must not report success when any side effect failed.
      if (!config.continueOnError) {
        throw new Error(
          `forEach had ${failures.length}/${collection.length} failed ` +
            `iteration(s): ${summary}`,
        );
      }
      // Failed items stay `null` and per-item errors are recorded, so this stays explicit.
      state.errors[step.id] =
        `${failures.length}/${collection.length} iteration(s) failed: ${summary}`;
    }

    state.steps[step.id] = results;
    state.status[step.id] = failures.length > 0 ? "partial" : "success";
    state.completed.push(step.id);
    return;
  }

  const payload = resolveMapping(
    config.inputMapping,
    state.params,
    state.steps,
  );
  const result = await callOnce(config, payload, state, client, endpoints);
  state.steps[step.id] = result;
  state.status[step.id] = "success";
  state.completed.push(step.id);
}
